(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0003.js"] = [{"id":"poem-13f5907af6166cb9127a180f","title":"醉落魄・一斛珠·清秋夜寂","author":"张抡","dynasty":"宋","verses":["清秋夜寂。","圆蟾素影流空碧。","都无一点浮云隔。","河汉光微，星斗淡无色。","日精欲炼须阴魄。","更深犹望清宵立。","坎离二物都收得。","独步瀛洲，方表大丹力。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-915","tags":[]},{"id":"poem-13f6741df5795560e90cdc24","title":"九三","author":"王梵志","dynasty":"唐","verses":["吾有十亩田，种在南山坡。","青松四五树，绿豆西三窠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-d744878a-dcd3-4d05-a253-e9fdfb613f28","tags":[]},{"id":"poem-13fd4d9c2245aac0b0fd2ad1","title":"恩赐丽正殿书院赐宴应制得林字","author":"张说","dynasty":"唐","verses":["东壁图书府，西园翰墨林。","诵诗闻国政，讲易见天心。","位窃和羹重，恩叨醉酒深。","载歌春兴曲，情竭为知音。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-恩賜麗正殿書院賜宴應制得林字","tags":[]},{"id":"poem-14023e5737ccf780cdba517a","title":"菩萨蛮·蓬莱院闭天台女","author":"李煜","dynasty":"五代","verses":["蓬莱院闭天台女，画堂昼寝人无语。","抛枕翠云光，绣衣闻异香。","潜来珠琐动，惊觉银屏梦。","脸慢笑盈盈，相看无限情。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-22","tags":[]},{"id":"poem-140778d47d35e379d514a967","title":"江行即事八首  其八","author":"李纲","dynasty":"宋","verses":["一重一掩翠参差，路入桃源客意迷。","江雾晓分山远近，浦鸥闲送櫂东西。","颇欣岭表佳泉石，闻道江南多鼓鼙。","稚子候门应念我，提携来共此幽栖。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-706f3953-d526-441a-806d-8e5dc6daa130","tags":[]},{"id":"poem-140cd4c281c2dfe4e97f215a","title":"春日杂兴  其五","author":"王同祖","dynasty":"宋","verses":["清明过了柳花飞，帘外萋萋草正肥。","唤起惜春情绪处，空山残月杜鹃啼。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-5bd07185-b03a-47a2-97aa-4917d1e9e8e1","tags":[]},{"id":"poem-140f9c281b53c2a48aa96b89","title":"烈祖","author":"佚名","dynasty":"先秦","verses":["嗟嗟烈祖！有秩斯祜。申锡无疆，及尔斯所。既载清酤，赉我思成。","亦有和羹，既戒既平。鬷假无言，时靡有争。绥我眉寿，黄耇无疆。","约軧错衡，八鸾鸧鸧。以假以享，我受命溥将。自天降康，丰年穰穰。","来假来飨，降福无疆。顾予烝尝，汤孙之将。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-301","tags":[]},{"id":"poem-14135388fb7d240c23ca0766","title":"咏史诗 白帝城","author":"胡曾","dynasty":"唐","verses":["蜀江一带向东倾，江上巍峩白帝城。","自古山河归圣主，子阳虚共汉家争。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-fe911240-bb2b-46da-841f-44a66a46a399","tags":[]},{"id":"poem-14171ba4bbffb42e86d595c8","title":"横吹曲辞 入塞曲 一","author":"僧贯休","dynasty":"唐","verses":["单于烽火动，都护去天涯。","别赐黄金甲，亲临白玉墀。","塞垣须静谧，师旅审安危。","定远条支宠，如今胜古时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-5dd824cf-e4bc-4a99-a85a-48e2688ebbb2","tags":[]},{"id":"poem-141b7cf45a471ae42ef6a67a","title":"虞美人·春情只到梨花薄","author":"纳兰性德","dynasty":"清","verses":["春情只到梨花薄，片片催零落。","夕阳何事近黄昏，不道人间犹有未招魂。","银笺别梦当时句，密绾同心苣。","为伊判作梦中人，索向画图清夜唤真真。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-199","tags":[]},{"id":"poem-141e3b9111bde8fb8f502313","title":"江城子·神仙楼观梵王宫","author":"毛并","dynasty":"宋","verses":["神仙楼观梵王宫。","月当中。","望难穷。","坐听三通，谯鼓报笼铜。","还忆当年京辇旧，车马会，五门东。","华堂歌舞间笙钟。","夕香蒙。","度花风。","翠袖传杯，争劝紫髯翁。","归去不堪春梦断，烟雨晓，乱山重。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-626","tags":[]},{"id":"poem-141ebe603e9e3b1b1e535b44","title":"咏风","author":"太宗皇帝","dynasty":"唐","verses":["萧条起关塞，摇飏下蓬瀛。","拂林花乱彩，响谷鸟分声。","披云罗影散，泛水织文生。","劳歌大风曲，威加四海清。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-7d4ab8fc-aa99-46f4-8571-54af4d4666bf","tags":[]},{"id":"poem-1432dc0af876d1c0497a5c35","title":"菩萨蛮·短船谁泊蒹葭渚","author":"苏庠","dynasty":"宋","verses":["短船谁泊蒹葭渚。","夜深远火明渔浦。","却忆槿花篱。","春声穿竹溪。","云山如昨好。","人自垂垂老。","心事有谁知。","月明霜满枝。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-690","tags":[]},{"id":"poem-1436044ec6011f4c88ec24f9","title":"送从翁中丞奉使黠戛斯六首 二","author":"赵嘏","dynasty":"唐","verses":["旌旗杳杳雁萧萧，春尽穷沙雪未消。","料得坚昆受宣后，始知公主已归朝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-5afc432e-1115-44f7-9dbb-2056ff04741b","tags":[]},{"id":"poem-143ffb501b7a408f055714b4","title":"粤俗","author":"谢景初","dynasty":"宋","verses":["粤俗嗜海物，鳞介无一遗。","虾蠃味已厚，况乃蟹与蜞。","潮来浦屿涨，遮捕张藩篱。","潮去沙满滩，拾掇盈篱箕。","杀烹数莫记，琐碎臭且奇。","苟务贪咀嚼，宁识暴殄悲。","蛟蜃吐云气，腹以人为饴。","呀口日肥大，洪波谁敢窥。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-fb17c8e0-2247-4fde-af7c-1e2aa0311556","tags":[]},{"id":"poem-1449ff01644b3bd9d2e85b70","title":"春怨","author":"郑愔","dynasty":"唐","verses":["春朝物候妍，愁妇镜台前。","风吹数蝶乱，露洗百花鲜。","试出褰罗幌，还来著锦筵。","曲中愁夜夜，楼上别年年。","不及随萧史，高飞向紫烟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-de56b324-ae5c-4da5-a3d0-5a83a12ce7d5","tags":["春天","闺怨"]},{"id":"poem-144aebc76d93dfee140dd9c6","title":"句","author":"朴昂","dynasty":"唐","verses":["明主十征何谢病，烟霞不许作尧臣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-4d34410a-0699-4fc0-b25e-c676d2b57219","tags":[]},{"id":"poem-144e44244be5b5c4175297fb","title":"浣溪沙·十八年来堕世间","author":"纳兰性德","dynasty":"清","verses":["十八年来堕世间，吹花嚼蕊弄冰弦。","多情情寄阿谁边。","紫玉钗斜灯影背，红绵粉冷枕函偏。","相看好处却无言。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-144","tags":[]},{"id":"poem-14502bddc19fb804ca8d0c9d","title":"点绛唇·燕雁无心","author":"姜夔","dynasty":"宋","verses":["燕雁无心，太湖西畔随云去。","数峰清苦。","商略黄昏雨。","第四桥边，拟共天随住。","今何许。","凭栏怀古。","残柳参差舞。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-121","tags":["宋词三百首","太湖"]},{"id":"poem-14558df45587652149c41c37","title":"自淇涉黄河途中作十三首 四","author":"高适","dynasty":"唐","verses":["南登滑台上，却望河淇间。","竹树夹流水，孤城对远山。","念兹川路阔，羡尔沙鸥闲。","长想别离处，犹无音信还。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-89150285-38e4-480d-87d6-95db4cb9a4ed","tags":["黄河"]},{"id":"poem-14559c314e9f7a4ac7fab9c4","title":"酒泉子·紫陌青门","author":"张泌","dynasty":"五代","verses":["紫陌青门，三十六宫春色。","御沟辇路暗相通，杏园风。","咸阳沽酒宝钗空，笑指未央归去。","插花走马落残红，月明中。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-42","tags":[]},{"id":"poem-145e5e26ae92b784f1b907f4","title":"菩萨蛮·萧萧几叶风兼雨","author":"纳兰性德","dynasty":"清","verses":["萧萧几叶风兼雨，离人偏识长更苦。","欹枕数秋天，蟾蜍下早弦。","夜寒惊被薄，泪与灯花落。","无处不伤心，轻尘在玉琴。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-177","tags":[]},{"id":"poem-14648144027f28f2ccf16801","title":"绿头鸭・多丽·玉人家","author":"贺铸","dynasty":"宋","verses":["玉人家，画楼珠箔临津。","托微风、彩箫流怨，断肠马上曾闻。","燕堂开、艳妆丛里，调琴思、认歌颦。","麝蜡烟浓，玉莲漏短，更衣不待酒初醺。","绣屏掩、枕鸳相就，香气渐暾暾。","回廊影，疏钟淡月，几许销魂。","翠钗分、银笺封泪，舞鞋从此生尘。","住兰舟、载将离恨，转南浦、背西曛。","记取明年，蔷薇谢后，佳期应未误行云。","凤城远，楚梅香嫩，先寄一枝春。","青门外，祗凭芳草，寻访郎君。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-219","tags":["宋词三百首"]},{"id":"poem-146f5eb2fc0fa531fab4f6ac","title":"秋末长兴寺作","author":"贯休","dynasty":"唐","verses":["荒寺古江滨，莓苔地绝尘。","长廊飞乱叶，寒雨更无人。","栗不和皱落，僧多到骨贫。","行行行未得，孤坐更谁亲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-d4ab7baf-95ea-4e7f-8058-f66e84bcef28","tags":[]},{"id":"poem-14863a652c77b4df089f38a8","title":"题玉涧八景八首  其一","author":"王柏","dynasty":"宋","verses":["画出女墙月，老子兴不浅。","谁识春光中，解使平湖歛。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-b582718f-218e-4e14-bbcb-7e99d297833f","tags":[]},{"id":"poem-1486b62c428364f6ffa3ddbb","title":"玉连环影","author":"纳兰性德","dynasty":"清","verses":["何处几叶萧萧雨。","湿尽檐花，花底人无语。","掩屏山，玉炉寒。","谁见两眉愁聚倚阑干。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-216","tags":[]},{"id":"poem-1486b7394137b58d7e1f45b3","title":"偶作五首 二","author":"贯休","dynasty":"唐","verses":["机生机，巧生巧，心镬烘烘日煎炒。","闯蜀眉嚬游海岛，扶桑椹熟金乌饱。","金乌饱，飞复飞，四天下人眼眙眙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-1bd1fcda-a97c-44b6-9fcf-4fc1ceaf4df5","tags":[]},{"id":"poem-148e0448e13d7d9b55931423","title":"湖南运使柯少卿用广西提刑曹司勋游岳麓寺韵送广西行俾令同赋","author":"华镇","dynasty":"宋","verses":["昔闻湘西寺，梦想投双脚。","身境隔楚越，攘臂无由攫。","此日陪胜集，当年意弥廓。","山环秀色远，地胜真兴托。","赤日朗泥金，彤霞焕涂雘。","追随得后乘，登顿闲芒𪨗。","穷幽际高深，历险遵厓堮。","北斗近在手，南溟消一酌。","天风韵球琳，世味膻醴酪。","蹑屐想王谢，登舟成李郭。","欣戚起参差，去住同纷错。","常时惜聚散，灵襟费恢拓。","契理在相忘，言志亦盍各。","无然结惆怅，聊用聆谈噱。","况当拥斧绣，不类居榛壑。","金石虽欲流，风云正相薄。","蕣华夕则陨，蜡味淡可嚼。","照坐兰玉明，挥翰珠玑落。","青嶂缭云构，红纱罗蜡爝。","景胜语难工，柔毫几频阁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-f123701f-83ef-4fa8-8c3f-be48aeb0d59b","tags":[]},{"id":"poem-149a4fe9bf93a60ac9c8c844","title":"摸鱼儿·对西风、鬓摇烟碧","author":"朱嗣发","dynasty":"宋","verses":["对西风、鬓摇烟碧，参差前事流水。","紫丝罗带鸳鸯结，的的镜盟钗誓。","浑不记、漫手织回文，几度欲心碎。","安花著蒂。","奈雨覆云翻，情宽分窄，石上玉簪脆。","朱楼外。","愁压空云欲坠。","月痕犹照无寐。","阴晴也只随天意。","枉了玉消香碎。","君且醉。","君不见、长门青草春风泪。","一时左计。","悔不早荆钗，暮天修竹，头白倚寒翠。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-98","tags":["宋词三百首"]},{"id":"poem-14a303354edb53d88d486a28","title":"秋日卢龙村舍","author":"徐铉","dynasty":"宋","verses":["置却人间事，闲从野老游。","树声村店晚，草色古城秋。","独鸟飞天外，闲云度陇头。","姓名君莫问，山木与虚舟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-7c8f8612-7efe-4476-be81-e4cfacf5eb03","tags":[]},{"id":"poem-14acfac279f71c5e3d600847","title":"王寺丞后圃","author":"释居简","dynasty":"宋","verses":["不独甘棠茂午阴，浄如止水照人心。","楼通阊阖天垂斗，云锁蜿蜒鼎篆金。","袖里有春还自乐，尊前无客不能吟。","古菱花里青青鬓，半点吴霜不敢侵。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-4759c823-612f-4dd3-9f08-89296306e10c","tags":[]},{"id":"poem-14bf2123697739060e6a4c54","title":"王摩诘画渡水罗汉赞","author":"李纲","dynasty":"宋","verses":["阿罗汉具大神通，飞锡凌空如履实。","渺然巨浸与天永，戏蹑一杯能径渡。","云何溪涧咫尺间，乃有种种难涉相。","前者己济气怡然，后者将涉有难色。","老病扶携壮者负，足探策引褰衣裾。","秘其神力不示人，如畏黄蘖所诃责。","我观一切诸有情，咸具神通并妙用。","空中示现十八变，正眼观时非吉祥。","善哉摩诘老画师，能以毫墨作佛亊。","稽首十六大声闻，皆悉回心等正觉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-64261437-c9e3-4b7a-b820-955af953f1fa","tags":[]},{"id":"poem-14c6f0c0d0961945fa4c1478","title":"浣溪沙·湓浦从君已十年","author":"张孝祥","dynasty":"宋","verses":["湓浦从君已十年。","京江仍许借归船。","相逢此地有因缘。","十万貔貅环武帐，三千珠翠入歌筵。","功成去作地行仙。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-363","tags":[]},{"id":"poem-14ca0a44e5fb925514416536","title":"春日杂兴十五首  其一四","author":"华镇","dynasty":"宋","verses":["春华杂丹素，芳心馥椒兰。","蝴蝶采其荣，交飞密为团。","轻须卷丝绪，弱翅剪冰纨。","栩栩婉有容，飞飞闲可观。","深丛密依倚，曲径恣盘桓。","日昃芳气消，露晞黄粉干。","繁华未零落，幽意已阑珊。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-8fd770f7-4dac-47c8-afe8-4fcc3f83d090","tags":[]},{"id":"poem-14cf201e1df6def726a43432","title":"酒泉子·秋雨联绵","author":"李珣","dynasty":"五代","verses":["秋雨联绵，声散败荷丛里。","那堪深夜枕前听，酒初醒。","牵愁惹思更无停，烛暗香凝天欲曙。","细和烟，冷和雨，透帘旌。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-39","tags":[]},{"id":"poem-14d6a3dfa8c38398123da20b","title":"游北湖","author":"罗隐","dynasty":"唐","verses":["醒心亭下水涵天，吏部风流三百年。","（见《舆地纪胜》卷五十七《郴州》。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-28872669-59a8-4cd8-bd41-fa065dce3267","tags":[]},{"id":"poem-14da6a5a68ca1c85bac332ce","title":"送稽亭山寺僧","author":"张籍","dynasty":"唐","verses":["师住稽亭高处寺，斜廊曲阁倚云开。","山门十里松间入，泉涧三重洞里来。","名岳寻游今已徧，家城礼谒便应回。","旧房到日闲吟后，林下还登说法台。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-82da9ec9-f213-4a87-b5e0-f419f984b8dc","tags":[]},{"id":"poem-14dc08ebec51ab5c97e45a50","title":"瑶花慢·朱钿宝","author":"周密","dynasty":"宋","verses":["朱钿宝。","天上飞琼，比人间春别。","江南江北，曾未见，谩拟梨云梅雪。","淮山春晚，问谁识、芳心高洁。","消几番、花落花开，老了玉关豪杰。","金壶翦送琼枝，看一骑红尘，香度瑶阙。","韶华正好，应自喜、初识长安蜂蝶。","杜郎老矣，想旧事、花须能说。","记少年，一梦扬州，二十四桥明月。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-94","tags":["宋词三百首"]},{"id":"poem-14e9969e70ca55c871384a2f","title":"木兰花慢·老来情味减","author":"辛弃疾","dynasty":"宋","verses":["老来情味减，对别酒、怯流年。","况屈指中秋，十分好月，不照人圆。","无情水、都不管，共西风、只等送归船。","秋晚莼鲈江上，夜深儿女灯前。","征衫。","便好去朝天。","玉殿正思贤。","想夜半承明，留教视草，却遣筹边。","长安故人问我，道寻常、泥酒只依然。","目断秋霄落雁，醉来时响空弦。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-212","tags":["宋词三百首"]},{"id":"poem-14eb0bf9830a28355c71fa3c","title":"点绛唇·石洞清寒","author":"曹勋","dynasty":"宋","verses":["石洞清寒，柳烟吹散松风静。","日华光映。","翠水环云径。","道境多闲，不是人间景。","谈清净。","道师歌咏。","花转云房影。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-205","tags":[]},{"id":"poem-14ebafd95bb6960f807adaa7","title":"太清舞·渔舟之子来何所","author":"史浩","dynasty":"宋","verses":["渔舟之子来何所。","尽相猜相语。","夜宿玉堂空，见火轮飞舞。","凡心有虑尚依然，复归指、维舟沙浦。","回首已茫茫，叹愚迷不悟。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-15","tags":[]},{"id":"poem-14f008152e735237c6635f07","title":"鲁郡途中遇徐十八录事","author":"高适","dynasty":"唐","verses":["谁谓嵩颍客，遂经邹鲁乡。","前临少昊墟，始觉东蒙长。","独行岂吾心，怀古激中肠。","圣人久已矣，游夏遥相望。","裴回野泽间，左右多悲伤。","日出见阙里，川平知汶阳。","弱冠负高节，十年思自强。","终然不得意，去去任行藏。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-50d96cb2-de4f-4cbe-bf62-3159b077d2f6","tags":[]},{"id":"poem-14fe3acb634b0f444e6864d2","title":"念奴娇·素娥睡起","author":"姚孝宁","dynasty":"宋","verses":["素娥睡起，驾冰轮碾破，一天秋绿。","醉倚高楼风露下，凛凛寒生肌粟。","横管孤吹，龙吟风劲，雪浪翻银屋。","壮游回首，会稽何限修竹。","今夜对月依然，尊前须快泻，山头鸣瀑。","吸此清光倾肺腑，洗我明珠千斛。","只恐蝉娟，明年依旧，衰鬓先成鹄。","举杯相劝，为予且挂团玉。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-824","tags":[]},{"id":"poem-15090eb112d86319f234c138","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["不丰岁，荒歉年，生离死别真可怜。","纵有八口人家，饥饿应难免。","子忍饥，妻忍寒。","痛哭声，恁哀怨。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5050","tags":[]},{"id":"poem-150a6269692399a8ff29df14","title":"题龙门寺","author":"陆海","dynasty":"唐","verses":["窗灯林霭里，闻磬水声中。","更与龙华会，炉烟满夕风。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-6971df43-734e-4388-a8d5-1b495931f02e","tags":[]},{"id":"poem-15142748ed590562c061fe0d","title":"谢王连州送海阳图","author":"李涉","dynasty":"唐","verses":["谢家为郡实风流，画得青山寄楚囚。","惊起草堂寒气晚，海阳潮水到床头。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-bff69f38-a9de-47a9-aa2b-ae8c4a47b7b8","tags":[]},{"id":"poem-1529f64e2b738833aca338c6","title":"幽州夜歌","author":"张说","dynasty":"唐","verses":["凉风吹夜雨，萧瑟动寒林。","正有高堂宴，能忘迟暮心。","军中宜剑舞，塞上重笳音。","不作边城将，谁知恩遇深。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-幽州夜歌","tags":[]},{"id":"poem-1533e562e117edf8a14e5e2d","title":"醉公子·漠漠秋云淡","author":"顾敻","dynasty":"五代","verses":["漠漠秋云淡，红耦香侵槛。","枕欹小山屏，金铺向晚扃。","睡起横波慢，独望情何限。","衰柳数声蝉，魂消似去年。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-34","tags":[]},{"id":"poem-15368a073435b174a6349d46","title":"问刘十九","author":"白居易","dynasty":"唐","verses":["绿螘新醅酒，红泥小火垆。","晚来天欲雪，能饮一杯无。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-9972f7bb-ae5b-49e4-87df-381386af66b6","tags":["唐诗三百首","五言绝句","生活","饮酒","友情"]},{"id":"poem-1536fd3201f6326e8d516f38","title":"醉后赠张九旭","author":"高适","dynasty":"唐","verses":["世上漫相识，此翁殊不然。","兴来书自圣，醉后语尤颠。","白发老闲事，青云在目前。","床头一壶酒，能更几回眠。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-醉後贈張九旭","tags":[]},{"id":"poem-15371f2f86865e8875d723d8","title":"王敬伯歌","author":"李端","dynasty":"唐","verses":["妾本舟中女，闻君江上琴。","君初感妾意，妾亦感君心。","遂出合欢被，同为交颈禽。","传杯唯畏浅，接膝犹嫌远。","侍婢奏箜篌，女郎歌宛转。","宛转怨如何，中庭霜渐多。","霜多叶可惜，昨日非今夕。","徒结万重欢，终成一宵客。","王敬伯，绿水青山从此隔。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-b0394c9f-7d5a-4880-a96a-b9211aecc6db","tags":[]},{"id":"poem-153f10a6ec5ebad6a11378ac","title":"再游玄都观","author":"刘禹锡","dynasty":"唐","verses":["百亩庭中半是苔，桃花净尽菜花开。","种桃道士归何处，前度刘郎今又来。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-再遊玄都觀","tags":[]},{"id":"poem-1558fc2168dab6b103e8f04c","title":"闻无相道人顺世五首 五","author":"贯休","dynasty":"唐","verses":["百千万亿偈，共他勿交涉。","所以那老人，密传与迦叶。","吾师得此法，不论劫不劫。","去矣不可留，无踪若为蹑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-02c5bb93-e6f6-4caf-8bfd-2d45a818d7ee","tags":[]},{"id":"poem-15658a96cced1d15dec9b9ad","title":"前腔","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(贴)娘行听告，常言人道：热心闲管招非，冷眼无些烦恼。","(旦)迎春，你如今不要开口罢！(贴)奴不合口多，奴不合口多，惹得官人嗔叫，累娘焦燥。","自今朝，闭口深藏舌，安身处处牢。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1731","tags":[]},{"id":"poem-15703401e441cb5df9665bd2","title":"秋郊夕望","author":"马戴","dynasty":"唐","verses":["度鸟向栖急，阴虫逢夜多。","余霞媚秋汉，迥月濯沧波。","蔓草将萎绝，流年其奈何。","耿然摇落思，独酌不成歌。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-59ecaa7b-6657-4be0-9b30-9188b5101bc0","tags":[]},{"id":"poem-15705a050bd829afc54e517c","title":"幺","author":"杨景贤","dynasty":"元","verses":["徒弟每诸般劝，师父独自慌。","俺女兵不用猴为将，女王岂用猪为相？如今女娘都爱唐三藏。","你休痴迷修行今世有来生，我则待长江后浪催前浪。","(女王做扯唐僧科)这正殿上不是说话的去处，俺两个后殿里去来。","(唐僧云)孙悟空救我。","(下)(行者云)我自也顾不得。","(诸女做捉番孙、猪、沙发科)(下)(女王扯唐僧上，云)唐僧，我和你成其夫妇，你则今日就做国王，如何？(唐僧云)善哉！我要取经哩。","(发科)(女王唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2333","tags":[]},{"id":"poem-15745424e4c465233f7ae996","title":"登香炉峰寄远人","author":"张祜","dynasty":"唐","verses":["前登香炉峰，却指湓城郡。","大江北潮海，崇岳南作镇。","相逢虎溪子，轻策聊一振。","水石动寒光，风松洒高韵。","忧来月成语，忽忽千里愤。","六朝空遗文，三国无尺烬。","孤禽下云久，远树入烟尽。","客恨猒山重，归心喜流顺。","故执行潇湘别，即此无音信。","憔悴十年心，谁人不缁磷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-d9e79943-6773-45dc-9ad0-a9754b7821f2","tags":[]},{"id":"poem-1574e564a8b68cee7d1ed4a4","title":"送淳于秀才兰陵觐省","author":"皎然","dynasty":"唐","verses":["欢言欲忘别，风信忽相惊。","柳浦归人思，兰陵春草生。","撷芳心未及，视枕恋常盈。","此去非长路，还如千里情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-f51d1cab-f27a-4c80-9ad2-38f00f169ec9","tags":[]},{"id":"poem-1578d06bf6b2b0e43e206374","title":"凤箫吟・芳草·锁离愁","author":"韩缜","dynasty":"宋","verses":["锁离愁，连绵无际，来时陌上初熏。","绣帏人念远，暗垂珠泪，泣送征轮。","长亭长在眼，更重重、远水孤云。","但望极楼高，尽日目断王孙。","消魂。","池塘别后，曾行处、绿妒轻裙。","恁时携素手，乱花飞絮里，缓步香。","朱颜空自改，向年年、芳意长新。","遍绿野，嬉游醉眠，莫负青春。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-14","tags":["宋词三百首"]},{"id":"poem-157a9104a5e0ec94fbf9b827","title":"晦日游大理韦卿城南别业四声依次用各六韵 四","author":"王维","dynasty":"唐","verses":["高馆临澄陂，旷然荡心目。","淡荡动云天，玲珑映墟曲。","鹊巢结空林，雉雊响幽谷。","应接无闲暇，徘徊以踯躅。","纡组上春堤，侧弁倚乔木。","弦望忽已晦，后期洲应绿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-fdd36dac-cff8-41ed-8cce-409f56c6634c","tags":[]},{"id":"poem-1588252b1af7c60dcacacea0","title":"夏日樊川别业即事","author":"刘得仁","dynasty":"唐","verses":["无事称无才，柴门亦罕开。","脱巾吟永日，著屐步荒台。","风卷微尘上，霆将暴雨来。","终南云渐合，咫尺失崔嵬。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-fe62a52d-e93a-4c54-8962-7641bafc1c57","tags":[]},{"id":"poem-158ca5fd9c1e091d79eaeb04","title":"甘州遍·春光好","author":"毛文锡","dynasty":"五代","verses":["春光好，公子爱闲游，足风流。","金鞍白马，雕弓宝剑，红缨锦襜出长揪。","花蔽膝，玉衔头。","寻芳逐胜欢宴，丝竹不曾休。","美人唱，揭调是《甘州》。醉红楼。","尧年舜日，乐圣永无忧。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-13","tags":[]},{"id":"poem-158d4ff196a9dbd22ed141ba","title":"感皇恩·七十在前头","author":"程大昌","dynasty":"宋","verses":["七十在前头，难言未老。","只是中间有些好。","鬒云虽瘦，未有一根华皓。","都缘心地静，无忧恼。","此际生朝，梅花献笑。","似向天边得新报。","孙枝秀雅，已挂恩袍春草。","定从欢喜处，添年考。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-234","tags":[]},{"id":"poem-159949ae18e4dedf126700e5","title":"投苏州卢郎中","author":"张祜","dynasty":"唐","verses":["三地分符宠更深，两方旌斾日骎骎。","蛟龙可是池中物，鳯鸟无非阁上音。","世重才人皆立绩，客依公子尽推心。","犹思谢尚经牛渚，曾听袁宏一夜吟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-f318ed52-7c91-4458-8c52-c5a264969731","tags":[]},{"id":"poem-159a0c610d110cd474258df5","title":"蔡秀才求予所作记作诗赠之时蔡移居","author":"陈造","dynasty":"宋","verses":["古人四壁居，今人犹叹息。","蔡子携百指，亦自无四壁。","分绝槟榔求，未断文字癖。","此行谁知己，所向尽艰食。","予文久自知，不作杯水直。","方君忍饥雷，可语宁此石。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-2d5c987e-1a5d-4635-9f30-3c2ccb83d535","tags":[]},{"id":"poem-15a35633a6908399dcaac5a1","title":"咏史诗 长平","author":"胡曾","dynasty":"唐","verses":["长平瓦震武安初，赵卒俄成戏鼎鱼。","四十万人俱下世，元戎何用读兵书。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-c6176dd3-1bdd-4031-99a1-0771c1baf7b4","tags":[]},{"id":"poem-15b2e7cc1833a9d331b17ce6","title":"江城子·春风旗鼓石头城","author":"张镃","dynasty":"宋","verses":["春风旗鼓石头城。","急麾兵。","斩长鲸。","缓带轻裘，乘胜讨蛮荆。","蚁聚蜂屯三十万，军面缚，赴行营。","舳舻千里大江横。","凯歌声。","犬羊惊。","尊俎风流，谈笑酒徐倾。","北望旄头今已灭，河汉淡，两台星。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-350","tags":[]},{"id":"poem-15b63b7f2b096d4f813cfccf","title":"河渎神·汾水碧依依","author":"孙光宪","dynasty":"五代","verses":["汾水碧依依，黄云落叶初飞。","翠华一去不言归，庙门空掩斜晖。","四壁阴森排古画，依旧琼轮羽驾。","小殿沉沉清夜，银灯飘落香灺。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-5","tags":[]},{"id":"poem-15c0753f1706501d3fccd40b","title":"送吏部刘相公除东川","author":"贯休","dynasty":"唐","verses":["帝念梓州民，年年战仗频。","山川无草木，烽火没烟尘。","政乱皆因乱，安人必藉仁。","皇天开白日，殷鼎辍诚臣。","一日离君侧，千官送渭滨。","酒倾红琥珀，马控白骐𬴊。","渥泽番番降，壶浆处处陈。","旌幢山色湿，邛僰鸟啼新。","帟幕还名俭，良医始姓秦。","军雄城似岳，地变物含春。","白必侵双鬓，清应诫四邻。","吾皇重命相，更合是何人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-292b47cc-a1bc-4c6a-aab1-bf808b3b459d","tags":[]},{"id":"poem-15cc17393e33d82f04cd1ed3","title":"萍乡春晚寓居（四首） 一","author":"沈彬","dynasty":"唐","verses":["向隅书剑坐销魂，心计艰难有泪痕。","三月不寻花下路，一春常闭雨中门。","闲时易得开书帙，贫手难求傍酒樽。","三十无成今四十，翊周安汉意空存。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-9184074c-ead2-43d1-8e56-ed3cbef2472a","tags":[]},{"id":"poem-15d5918c2bc7a8a4e1056b81","title":"咏史诗 西园","author":"胡曾","dynasty":"唐","verses":["月满西园夜未央，金风不动邺天凉。","高情公子多秋兴，更领诗人入醉乡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-cc265090-847e-4105-9fa3-5e40a93c715f","tags":[]},{"id":"poem-15d90c81051b9fd5de5d57f3","title":"菩萨蛮·天含残碧融春色","author":"毛熙震","dynasty":"五代","verses":["天含残碧融春色，五陵薄幸无消息。","尽日掩朱门，离愁暗断魂。","莺啼芳树暖，燕拂回塘满。","寂寞对屏山，相思醉梦间。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-12","tags":[]},{"id":"poem-15dbea2745464688c393790a","title":"偈","author":"释惟爽","dynasty":"宋","verses":["今朝六月旦，一年已过半。","奉报参玄人，识取娘生面。","娘生面，荐不荐。","鹭鸶飞入碧波中，抖擞一团银绣线。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-fa89fad3-b319-4640-aba2-d841821860c3","tags":[]},{"id":"poem-15e42069f8ba8a1b9df2324d","title":"江州重别薛六柳八二员外","author":"刘长卿","dynasty":"唐","verses":["生涯岂料承优诏，世事空知学醉歌。","江上月明胡鴈过，淮南木落楚山多。","寄身且喜沧洲近，顾影无如白发何。","今日龙钟人共弃，媿君犹遣慎风波。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-d9dd3520-9aab-4b1b-bd57-810f29391667","tags":["唐诗三百首","送别","七言律诗"]},{"id":"poem-15e6cdb77bb3ff4eb2a85438","title":"江外除夜","author":"曹松","dynasty":"唐","verses":["千门庭燎照楼台，总为年光急急催。","半夜腊因风卷去，五更春被角吹来。","宁无好鸟思花发，应有游鱼待冻开。","不是多歧渐平稳，谁能呼酒祝昭回。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-96b9012d-793b-4097-8ae8-e13582efb7bc","tags":[]},{"id":"poem-15f09f28907a2bf17c442966","title":"八拍蛮·云锁嫩黄烟柳细","author":"阎选","dynasty":"五代","verses":["云锁嫩黄烟柳细，风吹红蒂雪梅残。","光景不胜闺阁恨，行行坐坐黛眉攒。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-24","tags":[]},{"id":"poem-15fa8e7d8e2f755d3922214a","title":"榴花泣","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["守官如水，胸次莹无瑕。","薄税敛。","省刑罚，抚安民庶禁奸猾。","幸喜词清讼简。","无事早休衙。","(旦)依条按法，看惩一戒百谁不怕？待三年任满期瓜，诏书来早晚迁加。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8253","tags":[]},{"id":"poem-15fdf0a2d37412a02d9c943b","title":"解佩环・疏影·江空不渡","author":"彭元逊","dynasty":"宋","verses":["江空不渡，恨蘼芜杜若，零落无数。","远道荒寒，婉娩流年，望望美人迟暮。","风烟雨雪阴晴晚，更何须，春风千树。","尽孤城、落木萧萧，日夜江声流去。","日晏山深闻笛，恐他年流落，与子同赋。","事阔心违，交淡媒劳，蔓草沾衣多露。","汀洲窈窕馀醒寐，遗浮沈沣浦。","有白鸥淡月，微波寄语，逍遥容与。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-99","tags":["宋词三百首"]},{"id":"poem-1602dbfebb1611febb1c1cd1","title":"清平乐·上阳春晚","author":"温庭筠","dynasty":"唐","verses":["上阳春晚，宫女愁蛾浅。","新岁清平思同辇，争那长安路远。","凤帐鸳被徒熏，寂寞花锁千门。","竞把黄金买赋，为妾将上明君。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-0","tags":[]},{"id":"poem-160365218d6dcf488edce758","title":"白马金砂洞","author":"释居简","dynasty":"宋","verses":["准拟朝餐洞口霞，更穷泓碧涨桃花。","可曾石罅潴成玉，多是金边拣得沙。","符说有灵寻汉篆，人因鉴止见胡麻。","依稀似入天台路，不属刘家与阮家。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-d096d5c1-0564-4d75-8199-c89e84874297","tags":[]},{"id":"poem-16137767","title":"入若耶溪","author":"王籍","dynasty":"南朝梁","verses":["艅艎何泛泛，空水共悠悠。","阴霞生远岫，阳景逐回流。","蝉噪林逾静，鸟鸣山更幽。","此地动归念，长年悲倦游。"],"enabled":true,"collection":"历代名篇","source":"《文选》卷二十六王籍《入若耶溪》。","tags":["山水"]},{"id":"poem-1614490f5a531286d2309789","title":"西地锦","author":"无名氏《宦门子弟错立身》","dynasty":"元","verses":["当职心怀公正，更名播朝廷。","从官判断无私曲，管民乐升平。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-316","tags":[]},{"id":"poem-16207413497c50f5bd28642d","title":"送权二","author":"王维","dynasty":"唐","verses":["高人不可有，清论复何深。","一见如旧识，一言知道心。","明时当薄宦，解薜去中林。","芳草空隐处，白云余故岑。","韩侯久携手，河岳共幽寻。","怅别千余里，临堂鸣素琴。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-ee598cce-2501-42b3-8d77-1de2d9b58870","tags":[]},{"id":"poem-1629d6b96e6837472ee4d731","title":"寄贯休","author":"裴说","dynasty":"唐","verses":["忆昔与吾师，山中静论时。","总无方是法，难得始为诗。","冻犬眠干叶，饥禽啄病梨。","他年白莲社，犹许重相期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-618ec44f-ba5c-4aa7-8ab6-1c26b7f97774","tags":[]},{"id":"poem-162afc5b81af782a3db25569","title":"永明山居诗（六十九首） 三十七","author":"延寿","dynasty":"唐","verses":["息业怡神道最孤，藏名匿迹合良图。","冥心难使龙神见，出语须教海岳枯。","云驻庵前疑有意，鸟鸣庭际似相呼。","资持随分安排了，最急应须与道俱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-d849221c-b360-44ac-a964-4659a06810f1","tags":[]},{"id":"poem-163f80440f0e732422913bfb","title":"句","author":"郭忠恕","dynasty":"宋","verses":["为逢末劫归依佛，不就新恩叙理官。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-732667ea-5338-48f0-8a8a-29565c30a65a","tags":[]},{"id":"poem-164669c06472197dc3e487a9","title":"夜飞鹊・夜飞鹊慢·河桥送人处","author":"周邦彦","dynasty":"宋","verses":["河桥送人处，凉夜何其。","斜月远堕馀辉。","铜盘烛泪已流尽，霏霏凉露沾衣。","相将散离会，探风前津鼓，树杪参旗。","华骢会意，纵扬鞭、亦自行迟。","迢递路回清野，人语渐无闻，空带愁归。","何意重红满地，遗钿不见，斜径都迷。","兔葵燕麦，向残阳、欲与人齐。","但徘徊班草，欷歔酹酒，极望天西。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-474","tags":["宋词三百首"]},{"id":"poem-16473630602036d98b45a9df","title":"横吹曲辞 关山月二首 一","author":"戴叔伦","dynasty":"唐","verses":["月出照关山，秋风人未还。","清光无远近，乡泪半书间。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-6795674b-74d6-4ac8-94ef-792c9892c714","tags":[]},{"id":"poem-164788c66aaac37658a185bb","title":"韦轩游山遇雨","author":"王柏","dynasty":"宋","verses":["踏碎羊山黄叶堆，天飞细雨相车回。","二皇应讶来何晚，不忍听君话别杯。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-72561afa-aedc-4ee1-ac93-06d9fd380a9b","tags":[]},{"id":"poem-1655fa9e78617db6ec92176b","title":"奉和幸三会寺应制","author":"郑愔","dynasty":"唐","verses":["鸟籀遗新阁，龙旗访古台。","造书臣颉往，观迹帝羲来。","睿览山川匝，宸心宇宙该。","梵音随驻辇，天步接乘杯。","旧苑经寒露，残池问劫灰。","散花将捧日，俱喜圣慈开。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-3c5b156d-4240-4564-80cf-05df684b1800","tags":[]},{"id":"poem-165c026ec366e8097fa475f5","title":"谢裴司空寄马","author":"张籍","dynasty":"唐","verses":["𫘧耳新驹骏得名，司空远自寄书生。","乍离华廐移蹄涩，初到贫家举眼惊。","每被闲人来借问，多寻古寺独骑行。","长思岁旦沙堤上，得从鸣珂傍火城。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-611a7cbf-4679-427d-bf88-784eb53bcdd2","tags":[]},{"id":"poem-165c3f8899c982fa522d1b43","title":"师子院明初院主请","author":"释原妙","dynasty":"宋","verses":["鼻无两窍，眼露双睛。","十分无面目，一味得人憎。","将正续三世之业，等闲籍没。","向白云千峰之上，特地掀腾。","坐断死关，幸自恶声难掩。","那更被伊描邈，转见可怜生。","呵呵呵，三十年后，宁无人路见不平。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-9dbee42d-4294-479e-b380-b6db25fe70d1","tags":[]},{"id":"poem-16629a78c609a0b7b420f952","title":"玉真观","author":"张籍","dynasty":"唐","verses":["台殿曾为贵主家，春风吹尽竹窗纱。","院中仙女修香火，不许闲人入看花。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-31e6512c-2261-4dfa-9963-7c5fa2bb2f10","tags":[]},{"id":"poem-166838b588c1689c7d617359","title":"柳枝·吴王宫里色偏深","author":"牛峤","dynasty":"五代","verses":["吴王宫里色偏深，一簇纤条万缕金。","不愤钱塘苏小小，引郎松下结同心。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-46","tags":[]},{"id":"poem-16689ddcd908999ff1572c43","title":"金陵览古 半阳湖","author":"朱存","dynasty":"宋","verses":["江南龙节水为乡，水不纯阴又半阳。","一片湖光共深浅，两般泉脉异温凉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-2f3f8e5b-94a0-431f-9527-5a8fa05510d1","tags":[]},{"id":"poem-1677f1b371f1d446ee86e36f","title":"陪皮袭美陆鲁望重过鸟窠迹","author":"魏璞","dynasty":"唐","verses":["重探灵迹到空山，山下茅庵几叩关。","不为白云招客屐，那教清境接人寰。","螺池水色经年静，仙岭松声镇日闲。","拟约高贤同结社，好移竹室住前湾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-27afecd5-6b24-464d-8cc6-889810c6b0e4","tags":[]},{"id":"poem-167c1d9d5fe6dfae3493e205","title":"甘州子·露桃花里小楼深","author":"顾敻","dynasty":"五代","verses":["露桃花里小楼深，持玉盏，听瑶琴。","醉归青琐入鸳衾，月色照衣襟。","山枕上，翠钿镇眉心。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-44","tags":[]},{"id":"poem-168021a3ecca93b09d603aea","title":"赠施都正三首  其二","author":"陈造","dynasty":"宋","verses":["雨窗舞晦明，风竹作骚屑。","断无思归梦，人境两清绝。","道人气金玉，妙论挟冰雪。","未须金鼎丹，始可黑霜发。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-5cfd2eb8-e1ab-486b-9a01-cd5280e581fa","tags":[]},{"id":"poem-16958017753865411f607319","title":"和张文裕初寒十首  其七","author":"司马光","dynasty":"宋","verses":["何处初寒好，初寒叠石溪。","山斜改昏晓，路曲失东西。","拾栗走村稚，凿垣巢乳鸡。","我来闲拥褐，曝背草簷低。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-0b7256cc-3efa-4920-95ec-8f2f43b05e47","tags":[]},{"id":"poem-169934f0b36c61063ed3f94e","title":"赋得送贾岛谪长江","author":"李洞","dynasty":"唐","verses":["敲驴吟雪月，谪出国西门。","行傍长江影，愁深汨水魂。","笻携过竹寺，琴典在花村。","饥拾山松子，谁知贾傅孙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-8f73ea87-0ea1-4cdc-b224-ca76236abe77","tags":["长江"]},{"id":"poem-169c60b355894182dfcb1dd4","title":"题连云堡","author":"李涉","dynasty":"唐","verses":["由来天地有关扃，断壑连山接杳冥。","一出纵知边上事，满朝谁信语堪听。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-de1401d7-e100-4070-a35d-ad3d7de7b73c","tags":[]},{"id":"poem-169ecf3c5e052fc4d7cf4cae","title":"咸亨殿宴近臣诸亲柏梁体","author":"高宗皇帝","dynasty":"唐","verses":["屏欲除奢政返淳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-589c213c-6793-4ba6-b0d8-ef674ea4a544","tags":[]},{"id":"poem-16a02b0a4ca12e301111db24","title":"登百丈峰二首 一","author":"高适","dynasty":"唐","verses":["朝登百丈峰，遥望燕支道。","汉垒青冥间，胡天白如扫。","忆昔霍将军，连年此征讨。","匈奴终不灭，寒山徒草草。","唯见鸿雁飞，令人伤怀抱。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-d42cb59a-2f8d-4fe9-9db7-1e973995ef42","tags":[]},{"id":"poem-16b0c2bb76517165c9c8ce7a","title":"卜算子·云破月高悬","author":"吕渭老","dynasty":"宋","verses":["云破月高悬，照我双双泪。","人在朱桥转曲西，翠幕重重闭。","要见索商量，见了还无计。","心似长檠一点灯，到晓清清地。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-88","tags":[]},{"id":"poem-16c177de40dd0b7857fd6fba","title":"寄澜公二首 一","author":"贯休","dynasty":"唐","verses":["小一头应白，孤高住歙城。","不知安乐否，何以近无生。","烧逼鸿行侧，风干雪朕清。","途中逢此信，珍重未精诚。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-64d9609b-53d8-4eef-986a-64c6f645b180","tags":[]},{"id":"poem-16c5fb131748c1b86917cf90","title":"乾元中寓居同谷县作歌七首 二","author":"杜甫","dynasty":"唐","verses":["长镵长镵白木柄，我生托子以为命。","黄精无苗山雪盛，短衣数挽不掩胫。","此时与子空归来，男呻女吟四壁静。","鸣呼二歌兮歌始放，邻里为我色惆怅。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-c4b14b05-2686-43b7-9006-ceda18052b2a","tags":[]},{"id":"poem-16cb050893aa50703fc2b0e2","title":"宋中十首 四","author":"高适","dynasty":"唐","verses":["梁苑白日暮，梁山秋草时。","君王不可见，修竹令人悲。","九月桑叶尽，寒风鸣树枝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-89a6c133-8b77-4365-960f-79e7c3991f49","tags":[]},{"id":"poem-16ccfdaaa306d9c500ef8796","title":"浮梁金鳌山","author":"艾可叔","dynasty":"宋","verses":["鳌骨分明露浅洲，登临几度泛虚舟。","人生天地蜉蝣寄，世事江河日夜流。","前后朗吟坡老赋，逍遥终羡漆园游。","子真谷口今成趣，不为红尘枉白头。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-c2a02160-9cf5-4567-a9d4-38b74758ff57","tags":[]},{"id":"poem-16d144c17e49cee49dea8aba","title":"溪行","author":"释居简","dynasty":"宋","verses":["夭夭拍拍涨桃花，葑未全青荻已芽。","两行若无杨柳树，看来无处著韶华。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-34bc2f5e-99bf-49d4-b7a3-73a5a3eb4376","tags":[]},{"id":"poem-16d40c396c031e7f84cb5b03","title":"赠温幕张子常有诗见怀用韵因成五篇  其二","author":"华镇","dynasty":"宋","verses":["寂寥不见李膺舟，时倚西风叹逝流。","小吏忽来传秀句，春容顿觉满山幽。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-bef04635-948a-4a93-97f9-6720d8f3cd0b","tags":[]},{"id":"poem-16eb81c8e1e1c71959bf3942","title":"夏晚初霁南省寓直用余字","author":"厍狄履温","dynasty":"唐","verses":["薄宦因时泰，凉宵寓直初。","沈沈仙阁闭，的的暗更徐。","霁色连空上，炎氛入夜除。","星回南斗落，月度北窗虚。","待漏残灯照，含芳袭气余。","寐来冠不解，奏罢草仍书。","幕府慙良策，明曹媿散樗。","命轻徒有报，义重更难疎。","燕厦欣成托，鹓行滥所如。","晨趋当及早，复此戒朝车。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-78ca6b46-189b-425f-968e-e920be6ec2cb","tags":[]},{"id":"poem-16f0691422cfc82474e55486","title":"黄龙滚","author":"徐田臣《杀狗记》","dynasty":"元","verses":["太子泪双垂，太子泪双垂，投入江儿水。","风静浪平，楚王蹬岸离船去。","暗忆太子，偷弹珠泪，投西楚往晋国奔逃去。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1804","tags":[]},{"id":"poem-16f4f30f8922be6eb3c6d7f3","title":"韩奕","author":"佚名","dynasty":"先秦","verses":["奕奕梁山，维禹甸之，有倬其道。","韩侯受命，王亲命之：缵戎祖考，无废朕命。","夙夜匪解，虔共尔位，朕命不易。","粲不庭方，以佐戎辟。四牡奕奕，孔修且张。","韩侯入觐，以其介圭，入觐于王。","王锡韩侯，淑旗绥章，簟茀错衡。","玄衮赤舄，钩膺镂锡，鞹鞃浅幭，鞗革金厄。","韩侯出祖，出宿于屠。显父饯之，清酒百壶。","其殽维何？炰鳖鲜鱼。其蔌维何？维笋及蒲。","其赠维何？乘马路车。笾豆有且。侯氏燕胥。","韩侯取妻，汾王之甥，蹶父之子。","韩侯迎止，于蹶之里。","百两彭彭，八鸾锵锵，不显其光。","诸娣从之，祁祁如云。韩侯顾之，烂其盈门。","蹶父孔武，靡国不到。为韩姞相攸，莫如韩乐。","孔乐韩土，川泽𬣙𬣙，鲂𫚈甫甫，麀鹿噳噳。","有熊有罴，有猫有虎。庆既令居，韩姞燕誉。","溥彼韩城，燕师所完。以先祖受命，因时百蛮。","王锡韩侯，其追其貊。奄受北国，因以其伯。","实墉实壑，实亩实藉。献其貔皮，赤豹黄罴。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-260","tags":[]},{"id":"poem-16f7119ab7f048bb4b9c3096","title":"水龙吟·楚天千里清秋","author":"辛弃疾","dynasty":"宋","verses":["楚天千里清秋，水随天去秋无际。","遥岑远目，献愁供恨，玉簪螺髻。","落日楼头，断鸿声里，江南游子。","把吴钩看了，栏干拍遍，无人会、登临意。","休说鲈鱼堪。","尽西风、季鹰归未。","求田问舍，怕应羞见，刘郎才气。","可惜流年，忧愁风雨，树犹如此。","倩何人，唤取盈盈翠袖，英雄泪。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-208","tags":["宋词三百首"]},{"id":"poem-16faa89d1a0055f1d7a149d7","title":"早春行","author":"王维","dynasty":"唐","verses":["紫梅发初遍，黄鸟歌犹澁。","谁家折杨女，弄春如不及。","爱水看妆坐，羞人映花立。","香畏风吹散，衣愁露沾湿。","玉闺青门里，日落香车入。","游衍益相思，含啼向彩帷。","忆君长入梦，归晚更生疑。","不及红簷燕，双栖绿草时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-140031f2-d4e0-4555-b23b-92b10980f1ba","tags":["相思","哀怨","写人","闺怨"]},{"id":"poem-17091767ca8cf5543e4543c3","title":"秦门 胡亥","author":"周昙","dynasty":"唐","verses":["鹿马何难辨是非，宁劳卜筮问安危。","权臣为乱多如此，亡国时君不自知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-ff5f4b8e-0bf8-4406-822f-aa4290b1865d","tags":[]},{"id":"poem-170a1e4abf6aac1d6d29991d","title":"句","author":"李建勋","dynasty":"唐","verses":["一人看上马，双节引还乡。","（同前。","）（〖1〗《江南余载》：宋齐丘出镇洪州，诏赐锦袍，烈祖〖李昪〗亲为衣之。","李建勋赠诗有「一人看上马，双节引还乡」之句，时论荣之。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-e5e78e32-a625-4d91-8ead-86a5e6f41091","tags":[]},{"id":"poem-170b9c44c6e31a63a61be8cb","title":"密雨","author":"华镇","dynasty":"宋","verses":["昨夜好风月，须明陟路岐。","阴云生陇上，密雨满天涯。","岂患泥涂恶，难堪仆马疲。","却愁期会失，心绪乱如丝。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-2f634bf6-cd20-427f-90e1-b38859a44e30","tags":[]},{"id":"poem-1710071a51f03f6005c6318a","title":"醉起","author":"赵崇嶓","dynasty":"宋","verses":["醉起西窗日欲斜，新烟初试雨前茶。","川原春意无聊頼，开尽桐花到柿花。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-b11330ce-b119-4906-879d-b97463ac98fd","tags":[]},{"id":"poem-1722b84e2fac3ad50f4747d2","title":"寄处士梁烛","author":"张乔","dynasty":"唐","verses":["贤哉君子风，讽与古人同。","采药楚云里，移家湘水东。","星霜秋野阔，雨雹夜山空。","早晚相招隐，深耕老此中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-6c9f6ef2-3e5b-49e9-ae32-b6fdf7b02f80","tags":[]},{"id":"poem-1726ab0142c239778f4c28e2","title":"玉楼春·晚妆初了明肌雪","author":"李煜","dynasty":"五代","verses":["晚妆初了明肌雪，春殿嫔娥鱼贯列。","笙箫吹断水云间，重按霓裳歌遍彻。","临春谁更飘香屑？醉拍栏杆情味切。","归时休放烛光红，待踏马啼清夜月。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-28","tags":[]},{"id":"poem-173162de8fab7fc03a076bed","title":"腊月二日携家城东观梅夜归  其三","author":"张栻","dynasty":"宋","verses":["晴日东山饱看花，归来野路已昏鸦。","坡头认得疎篱处，薝卜林中李老家。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-f14ef449-3d47-4cb9-bc78-42f8a2b2a584","tags":[]},{"id":"poem-17351cfae7cd68b28f03e77b","title":"江神子・江城子·长安门外小林丘","author":"吴文英","dynasty":"宋","verses":["长安门外小林丘。","碧壶秋。","浴轻鸥。","不放啼红，流水通宫沟。","时有晴空云过影，华镜里，翳鱼游。","绮罗尘满九衢头。","晚香楼。","夕阳收。","波面琴高，仙子驾黄虬。","清磬数声人定了，池上月，照虚舟。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-508","tags":[]},{"id":"poem-1735d88dce8d1813948eaae9","title":"玉楼春·柳映玉楼春日晚","author":"顾敻","dynasty":"五代","verses":["柳映玉楼春日晚，雨细风轻烟草软。","画堂鹦鹉语雕笼，金粉小屏犹半掩。","香灭绣帷人寂寂，倚槛无言愁思远。","恨郎何处纵疏狂，长使含啼眉不展。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-47","tags":[]},{"id":"poem-173601d30dff8b85da5c911d","title":"晚春花","author":"项斯","dynasty":"唐","verses":["阴洞日光薄，花开不及时。","当春无半树，经烧足空枝。","疎与香风会，细将泉影移。","此中人到少，开尽几人知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-17299dfe-e9be-43d4-a1f8-684d03c32655","tags":[]},{"id":"poem-17398440852343bf3399e09d","title":"使辽作十四首  其九","author":"刘跂","dynasty":"宋","verses":["一作重山去，频看破镜飞。","长悲青冢怨，莫忘白登围。","礼觉周旋异，心知笑语非。","南飞何处鸟，安得与俱归。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-2cbb922e-e114-4f2a-955a-277b8b7adef7","tags":[]},{"id":"poem-1742ac4f532e28eadb95a097","title":"客饷新橙有感","author":"李纲","dynasty":"宋","verses":["湖外新橙也自黄，故人相赠解包香。","捣虀正鲙双鱼美，荐酒聊持一瓣尝。","湛岘旧栽千树橘，洞庭初落满林霜。","木奴供给何须道，怅望东吴云水郷。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-e1119d87-6fd2-4aba-8c49-5f3988147f60","tags":["洞庭湖"]},{"id":"poem-1744f38043cbae8605fd5245","title":"宿长安苏雍主簿厅","author":"李洞","dynasty":"唐","verses":["县对数峰云，官清主簿贫。","听更池上鹤，伴值岳阳人。","井锁煎茶水，厅关捣药尘。","往来多屣步，同舍即诸邻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-b4829580-dddf-4cec-8191-e08d9bc3b17d","tags":[]},{"id":"poem-174f33fbb414445974860d91","title":"奉同卢使君幼平游精舍寺","author":"皎然","dynasty":"唐","verses":["影刹西方在，虚空翠色分。","人天霁后见，猨鸟定中闻。","真界隐青壁，春山凌白云。","今朝石门会，千古仰斯文。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-39c7a954-06d2-4886-815f-33df6c3ccba2","tags":[]},{"id":"poem-1752d3bbddaebf5333b54779","title":"度巴硖（伯三六一九[一]）","author":"李邕","dynasty":"唐","verses":["客从巴硖度（水渡）[二]，传子（尔）诉（溯）行舟。","是日风波济（霁）（蒋云「济」有「止」意，《庄子》、《淮南子》中均有〖风济〗的用法，不必改。","），高塘（堂）[三]雨半收。","青山满蜀道，渌（绿）水向荆州。","不作书相慰（问），何（谁）能散（慰）别愁。","（皎然《诗式》卷三引「青山满蜀道，渌水向荆州」二句，作「崔颢《别人》」。","）（[一]按原卷载诗三首：一《彩云篇》，二《度巴峡》，三《秋夜泊江渚》。","第一首题下有李邕名。","检《全唐诗》第一第三两首正是李邕作，但第一首诗题作「咏云」，第三首残。","[二]按此诗见《全唐诗》二函九册，谓为崔颢作，题作『赠卢八象』。","故此据敦煌卷先用互著例载入李邕，然后据《全唐诗》校其异文，凡九事。","兹作说明于第一事下。","[三]俞云：「『高塘』应作『高唐』，两本俱误。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-ed223f71-efc4-4457-b27d-3e49ff709b32","tags":[]},{"id":"poem-1753b90f014b9b5b21753453","title":"林中独醒","author":"刘言史","dynasty":"唐","verses":["晚来林沼静，独坐间瓢尊。","向己非前迹，齐心欲不言。","微凉生乱筿，轻馥起孤萱。","未得浑无事，瓜田草正繁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-35d39e8c-a34a-4a4b-b569-6f9a87b44b05","tags":[]},{"id":"poem-175fe655e0e59819a08a4622","title":"·","author":"裴说","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-d1a18c35-c7c3-46cf-b19e-180158f9ba05","tags":[]},{"id":"poem-1764b30ecf48270deef3802c","title":"落花","author":"释赞宁","dynasty":"宋","verses":["蝶醉蜂狂香正浓，晚来阶下坠衰红。","开时费尽阳和力，落处难禁一阵风。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-596fa2db-15ca-47e3-9ec2-2e22ba32726c","tags":[]},{"id":"poem-176d278bebf52acefe6c954c","title":"临江仙·八字山头来较晚","author":"王质","dynasty":"宋","verses":["八字山头来较晚，彩云未散南楼。","夕阳千丈映帘钩。","君侯如欲老，江水莫教流。","扇底清歌尘不动，胡床明月清秋。","天浆为浪玉为舟。","酒阑君便起。","归去立班头。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-336","tags":[]},{"id":"poem-177f7413a64c169b134f563c","title":"郊庙歌辞 享龙池乐章 第五章","author":"姜皎","dynasty":"唐","verses":["龙池初出此龙山，常经此地谒龙颜。","日日芙蓉生夏水，年年杨柳变春湾。","尧坛宝匣余烟雾，舜海渔舟尚往还。","愿似飘飖五云影，从来从去九天间。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-037a76e5-2949-43de-850c-5bf8f5010ffd","tags":[]},{"id":"poem-17892547c6661f3960a1ef8f","title":"谒金门·人已醉","author":"韩淲","dynasty":"宋","verses":["人已醉。","溪北溪南春意。","击鼓吹箫花落未。","杏梅桃共李。","水底鱼龙惊起。","推枕月明千里。","伊吕衰翁徒尔耳。","我怀犹未是。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-445","tags":[]},{"id":"poem-178fefc5521c88d9533832a8","title":"登骊山高顶寓目","author":"中宗皇帝","dynasty":"唐","verses":["四郊秦汉国，八水帝王都。","阊阖雄里闬，城阙壮规模。","贯渭称天邑，含岐实奥区。","金门披玉馆，因此识皇图。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-c4305274-656b-4379-a658-eed9909fbaa2","tags":[]},{"id":"poem-17a2c2e9c82f51b0e695cd0a","title":"献衷心·见好花颜色","author":"欧阳炯","dynasty":"五代","verses":["见好花颜色，争笑东风。","双脸上，晚妆同。","闭小楼深阁，春景重重。","三五夜，偏有恨，月明中。","情未已，信曾通，满衣犹自染檀红。","恨不如双燕，飞舞帘栊。","春欲暮，残絮尽，柳条空。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-8","tags":[]},{"id":"poem-17ab291715a0d0bf3152872b","title":"玉楼春","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["冥冥长夜不知晓，寂寂空山几度秋。","泉下长眠人醒未，悲风萧瑟起松楸。","老汉曾蒙赵五娘之所托，教我与他看管这坟台。","这几日有些贫冗，不及来看。","呀！怎地？(末介唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5235","tags":[]},{"id":"poem-17ac7bf32edfee4706973296","title":"同邢判官寻龙湍观归湖中","author":"孙逖","dynasty":"唐","verses":["星使下仙京，云湖喜昼晴。","更从探穴处，还作櫂歌行。","丝管荷风入，帘帷竹气清。","莫愁归路远，水月夜虚明。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-05b87ce2-d432-48d8-ae41-e3328cb6008a","tags":[]},{"id":"poem-17b13cdf4f16c9d4f75f06f7","title":"句  其二","author":"张徽","dynasty":"宋","verses":["晓塔影分山店北，暮钟声落海门西。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-12c7c44b-b141-47ee-8c98-e20a75527082","tags":[]},{"id":"poem-17ca4f4713a6040873c80329","title":"宫词 二","author":"张籍","dynasty":"唐","verses":["黄金捍拨紫檀槽，弦索初张调更高。","尽理昨来新上曲，内官帘外送樱桃。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-ac0ef485-8298-4910-92e3-45c941babf93","tags":[]},{"id":"poem-17cecddee4ab2f8dcd04cd7a","title":"画堂春·摩围小隐枕蛮江","author":"黄庭坚","dynasty":"宋","verses":["摩围小隐枕蛮江。","蛛丝闲锁晴窗。","水风山影上修廊。","不到晚来凉。","相伴蝶穿花径，独飞鸥舞春光。","不因送客下绳床。","添火炷炉香。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-703","tags":[]},{"id":"poem-17cff9f7ff4f60eeaa63fce5","title":"厅事之西因依墉壑为山数仞有悬水焉予理戎之暇聊以息䜩此相国张公之所作也缅怀高致时濯尘缨即事寄言而赋斯什","author":"裴度","dynasty":"唐","verses":["奇峰似天作，半倚增城隅。","何处通泉脉，潺湲竟朝晡。","挂石悬一带，洒荷散千珠。","固宜赏高人，何为对武夫？","鼓鼙时铿{言訇}，吏卒亦喧呼。","愧尔来我所，顾我非尔徒。","乃是风流相，昔尝居此都。","能移造化力，雅与山水俱。","多慙受成者，得此聊自娱。","（见《分门纂类唐歌诗》残本第三册《天地山川类》卷三十二。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-c8c90034-c629-4fed-ad9d-d9100fc1e130","tags":[]},{"id":"poem-17d1a4b866eb01126478b1e4","title":"夏日登车盖亭","author":"蔡确","dynasty":"宋","verses":["纸屏石枕竹方床，手倦抛书午梦长。","睡起莞然成独笑，数声渔笛在沧浪。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-夏日登車蓋亭","tags":[]},{"id":"poem-17d6b3eaf1ca2c7483916422","title":"寄左省杜拾遗","author":"岑参","dynasty":"唐","verses":["联步趋丹陛，分曹限紫微。","晓随天仗入，暮惹御香归。","白发悲花落，青云羡鸟飞。","圣朝无阙事，自觉谏书稀。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-2779f710-4ab4-46cb-a2b6-1889752f26c2","tags":["唐诗三百首","仕途","五言律诗","感慨"]},{"id":"poem-17daeec6f5288a5ee59beeba","title":"洗兵马","author":"杜甫","dynasty":"唐","verses":["中兴诸将收山东，捷书日报清昼同。","河广传闻一苇过，胡危命在破竹中。","祗残邺城不日得，独任朔方无限功。","京师皆骑汗血马，回纥喂肉葡萄宫。","已喜皇威清海岱，常思仙仗过崆峒。","三年笛里关山月，万国兵前草木风。","成王功大心转小，郭相谋深古来少。","司徒清鉴悬明镜，尚书气与秋天杳。","二三豪俊为时出，整顿乾坤济时了。","东走无复忆鲈鱼，南飞觉有安巢鸟。","青春复随冠冕入，紫禁正耐烟花绕。","鹤禁通霄凤辇备，鸡鸣问寝龙楼晓。","攀龙附凤势莫当，天下尽化为侯王。","汝等岂知蒙帝力，时来不得夸身强。","关中既留萧丞相，幕下复用张子房。","张公一生江海客，身长九尺须眉苍。","征起适遇风云会，扶颠始知筹策良。","青袍白马更何有，后汉今周喜再昌。","寸地尺天皆入贡，奇祥异瑞争来送。","不知何国致白环，复道诸山得银瓮。","隐士休歌紫芝曲，词人解撰河清颂。","田家望望惜雨干，布谷处处催春种。","淇上健儿归莫嬾，城南思妇愁多梦。","安得壮士挽天河，净洗甲兵长不用。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-26a0266d-313c-4911-b629-2418556d1b03","tags":["喜悦","抒情","战争"]},{"id":"poem-17f6f26b034bf888d7042da8","title":"赛红娘","author":"无名氏《张协状元》","dynasty":"元","verses":["先来小生心儿闷，见贫女又嫁。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2551","tags":[]},{"id":"poem-17f71e8c762d4a34b5b5f29f","title":"河满子·正是破瓜年几","author":"和凝","dynasty":"五代","verses":["正是破瓜年几，含情惯得人饶。","桃李精神鹦鹉舌，可堪虚度良宵。","却爱蓝罗裙子，羡他长束纤腰。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-20","tags":[]},{"id":"poem-17f7209850088d08278433a7","title":"子规","author":"来鹄","dynasty":"唐","verses":["月落空山闻数声，此时孤馆酒初醒。","投人语若似伊泪，口畔血流应始听。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-91a8a81a-bc86-4fc2-96c9-57ea31235e29","tags":[]},{"id":"poem-17f9967a10ca59e790ccb660","title":"荷叶杯·我忆君诗最苦","author":"顾敻","dynasty":"五代","verses":["我忆君诗最苦，知否。","字字尽关心，红笺写寄表情深。","吟么吟，吟么吟。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-26","tags":[]},{"id":"poem-1807fd62856645dbe50dde50","title":"东坡居士作水陆于金山相招足疮不能往作此以寄之","author":"米芾","dynasty":"宋","verses":["久阴障夺佳山川，长澜四溢鱼龙渊。","众看李郭渡浮玉，晴风扫出清明天。","颇闻妙力开大施，足病不列诸方仙。","想应苍壁有垂露，照水百怪愁寒烟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-0acd5a44-7e9a-4fde-b59f-74dbc0ec352d","tags":[]},{"id":"poem-180e532b931e8c95ced499a8","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(丑)撒盐未是比宜，不若柳絮风吹。","看氏空素魄团圆，并无-点尘翳。","看梅花香清韵美，比三姐娇容无二。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8803","tags":[]},{"id":"poem-1822583acfdc1b0e8e5b8c13","title":"浣溪沙·新妇滩头眉黛愁","author":"黄庭坚","dynasty":"宋","verses":["新妇滩头眉黛愁。","女儿浦口眼波秋。","惊鱼错认月沈钩。","青箬笠前无限事，绿蓑衣底一时休。","斜风吹雨转船头。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-730","tags":[]},{"id":"poem-18231a6fbf7ba4f7544f618f","title":"崔九欲往南山马上口号与别","author":"裴迪","dynasty":"唐","verses":["归山深浅去，须尽丘壑美。","莫学武陵人，暂游桃源里。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-80fe70cd-6e63-48eb-9c1e-ab26330d45d9","tags":["唐诗三百首","离别","五言绝句","规劝"]},{"id":"poem-18280f2451e8d427f2c3d4d8","title":"喜迁莺·烛飘花","author":"晏殊","dynasty":"宋","verses":["烛飘花，香掩烬。","中夜酒初醒。","画楼残点两三声。","窗外月胧明。","晓帘垂，惊鹊去。","好梦不知何处。","南园春色已归来。","庭树有寒梅。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-472","tags":[]},{"id":"poem-182b494f42fa103e097525a6","title":"饮湖上初晴后雨","author":"苏轼","dynasty":"宋","verses":["水光潋滟晴方好，山色空蒙雨亦奇。","欲把西湖比西子，淡妆浓抹总相宜。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-飲湖上初晴後雨","tags":[]},{"id":"poem-182c0ec4439fed978d299c87","title":"与诸同僚偶会赋八题 坐久月初上","author":"苏颂","dynasty":"宋","verses":["高轩微雨过，初夕凉风生。","兀坐正幽寂，云间月华明。","移榻向寒阶，遥望孤蟾清。","所思故人远，对此伤予情。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-f325962c-49e1-4b6d-aebf-c1eede2326e2","tags":[]},{"id":"poem-182ff6995a233d300ffb7969","title":"送胡真师还西山","author":"明皇帝","dynasty":"唐","verses":["仙客厌人间，孤云比性闲。","话离情未已，烟水万重山。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-adfebde8-4ae5-47f8-9cd6-536c584fb6f6","tags":[]},{"id":"poem-18370fad0afd53dcb454e3f7","title":"送日本使还","author":"徐凝","dynasty":"唐","verses":["绝国将无外，扶桑更有东。","来朝逢圣日，归去及秋风。","夜泛潮回际，晨征苍莽中。","鲸波腾水府，蜃气壮仙宫。","天眷何期远，王文久已同。","相望杳不见，离恨托飞鸿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-c2c273aa-9617-4100-bbca-193f58f31d5f","tags":[]},{"id":"poem-184ab51b09ee5754f58c2889","title":"甫田","author":"佚名","dynasty":"先秦","verses":["倬彼甫田，岁取十千。我取其陈，食我农人。自古有年。","今适南亩，或耘或耔。黍稷薿薿，攸介攸止，烝我髦士。","以我齐明，与我牺羊，以社以方。我田既臧，农夫之庆。","琴瑟击鼓，以御田祖。以祈甘雨，以介我稷黍，以谷我士女。","曾孙来止，以其妇子。馌彼南亩，田畯至喜。攘其左右，尝其旨否。禾易长亩，终善且有。曾孙不怒，农夫克敏。","曾孙之稼，如茨如梁。曾孙之庾，如坻如京。乃求千斯仓，乃求万斯箱。黍稷稻粱，农夫之庆。报以介福，万寿无疆。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-210","tags":[]},{"id":"poem-1853a0e3134dddfc865d5c36","title":"沈正卿示探梅诗次韵","author":"曾协","dynasty":"宋","verses":["数点微明已露奇，解颜相见却先知。","携壶拟醉无穷树，走马来看第一枝。","照水意闲真我辈，酿寒云重正花时。","自从亲识春风面，不信良工画有诗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-53454636-5415-48ff-877f-75be30f2c92d","tags":[]},{"id":"poem-1855d41469ec1e80f7b637c3","title":"送醉画王处士","author":"李洞","dynasty":"唐","verses":["几年乘兴住南吴，狂醉兰舟夜落湖。","别后鹤毛描转细，近来牛角饮还麄。","同餐夏果山何处，共钓秋涛石在无。","关下相逢怪予老，篇章役思绕寰区。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-657d4c9f-abdc-42b4-a9c0-de4e41151adf","tags":[]},{"id":"poem-18692adc81055f15176394c9","title":"扬州怀古","author":"李益","dynasty":"唐","verses":["故国歌钟地，长桥车马尘。","彭城阁边柳，偏似不胜春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-9f62397a-8eef-4408-81dc-2cb54b55a866","tags":[]},{"id":"poem-186d4a4bd6843eda109019a9","title":"朝中措·沙明波净小汀洲","author":"张抡","dynasty":"宋","verses":["沙明波净小汀洲。","枫落洞庭秋。","红蓼白苹深处，晚风吹转船头。","鲈鱼钓得，银丝旋鲙，白酒新𥬠。","一笑月寒烟暝，人间万事都休。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-946","tags":["洞庭湖"]},{"id":"poem-186dcf82401f6bc5dd3bacc6","title":"兵要望江南 医方第二十九（十六首） 八","author":"易静","dynasty":"唐","verses":["金伤者，脑髓出非常。","颈咽喉中声沸者，两目直视痛难当，血似水流（辛本作「泉」）塘。","（似此，皆不治而难医也。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-1b5499d5-9639-4494-808c-bad8cb1f4593","tags":[]},{"id":"poem-18740f1ba80a6cf76bcb5085","title":"川拨棹","author":"无名氏《张协状元》","dynasty":"元","verses":["为孩儿，特特来蜀地。","满目薄芜见古庙，教人转悲，我寻思珠泪垂。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2697","tags":[]},{"id":"poem-1874a691ec1ba864e0a2638a","title":"劝人 一","author":"义存","dynasty":"唐","verses":["莫道肯去易，肯去也大难。","虚空满天下，迷人坐不安。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-a0ff47b8-174c-4afb-af15-ce8c8cf8b02a","tags":[]},{"id":"poem-18769e896af06957d9e0cbc5","title":"十二时偈 三","author":"文偃","dynasty":"唐","verses":["平旦寅，三昧圆光证法身。","大千世界掌中收，色透髑髅谁得亲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-391ca6fa-fbee-41ca-a8bf-e41afe49ff09","tags":[]},{"id":"poem-187b88c7109de23e5c1c3ea3","title":"和谭炼师见寄","author":"徐铉","dynasty":"宋","verses":["一别高人世事多，归山歧路转蹉跎。","定知上药延衰齿，每忆玄谈养太和。","任道人生如梦寐，也从时态起风波。","锦囊真箓遥相许，只待飙轮更一过。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-803b0032-15b8-42a2-9749-a7389935988b","tags":[]},{"id":"poem-1883e0ef638012eac8eabd8b","title":"六叹 三","author":"李涉","dynasty":"唐","verses":["汉臣一没丁零塞，牧羊西过阴沙外。","朝凭南鴈信难回，夜望北辰心独在。","汉家茅土横九州，高门长戟封王侯。","但将钟鼓悦私爱，肯以犬羊为国羞。","夜宿寒云卧冰雪，严风触刃垂旌节。","丁年奉使白头归，泣尽李陵衣上血。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-09e35871-4478-4c35-ac32-81e401b05360","tags":[]},{"id":"poem-18868459af29e623979b952c","title":"寄杨侍御","author":"包何","dynasty":"唐","verses":["一官何幸得同时，十载无媒独见遗。","今日不论腰下组，请君看取鬓边丝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-2a8dc382-dabc-4d44-933a-a9cd5d1d198f","tags":[]},{"id":"poem-1889cf954bb4db810295bcd1","title":"牛头庵颂","author":"文益","dynasty":"唐","verses":["国城南，祖师庵。","庵旧址，依云岚。","兽驯淑，人相参。","忽有心，终不堪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-a3635183-630c-4fb3-a340-ba5fd4660965","tags":[]},{"id":"poem-188dc6b51079658c65973220","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["我做媒婆甚艰辛，寻趁。","有个新郎要求亲，最紧。","我每只得便忙奔，讨信。","(介)路上更有早行人，心闷。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4963","tags":[]},{"id":"poem-1894676ff41432e6929ccba8","title":"长庆春","author":"徐凝","dynasty":"唐","verses":["山头水色薄笼烟，久客新愁长庆年。","身上五劳仍病酒，夭桃窗下背花眠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-37e22d3d-2784-4bc4-bcc9-6984dc6f668b","tags":[]},{"id":"poem-1898cddcfb0e31feb57e36da","title":"早秋山中作","author":"李山甫","dynasty":"唐","verses":["荣枯无路入千峰，肥遯谁谐此志同。","司寇亦曾遭鲁黜，步兵何事哭途穷。","桧松瘦健滴秋露，户牖虚明生晚风。","山思更清人影绝，陇云飞入草堂中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-5b184397-9da2-44e7-be9b-b73373769e30","tags":[]},{"id":"poem-18a26fb9bab8627019275933","title":"句","author":"陆侍御","dynasty":"唐","verses":["今年闰在春三月，剩见金陵一月花。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-536dade1-ad26-4bb7-a91d-392a7c3e8ea8","tags":[]},{"id":"poem-18a2881e9a8295fe462dbae4","title":"雨中宿僧院","author":"张乔","dynasty":"唐","verses":["千灯有宿因，长老许相亲。","夜永楼台雨，更深江海人。","劳生无了日，妄念起微尘。","不是真如理，何门静此身。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-3d94b8b1-d00c-4667-a411-3117ac16e7a4","tags":[]},{"id":"poem-18a6c6572bda86cbfa2f03fc","title":"临江仙·闻道洛阳花正好","author":"王以宁","dynasty":"宋","verses":["闻道洛阳花正好，家家遮户春风。","道人饮处百壶空。","年年花下醉，看尽几番红。","此拐又从何处去，飘蓬一任西东。","语声虽异笑声同。","一轮清夜月，何处不相逢。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-73","tags":[]},{"id":"poem-18a98930670c0571608c3886","title":"寄拄杖上王使君","author":"贯休","dynasty":"唐","verses":["拄杖邻僧与，殊常不可名。","一条黳玉重，百两紫金轻。","有乳盘春力，无心合道情。","惟宜高处著，将寄谢宣城。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-c9b1c5b3-00a4-4bde-81ab-0c181431baff","tags":[]},{"id":"poem-18aee8b630b0cb7a77ceff74","title":"台州郡治十二诗太守尤延之命赋 参云亭","author":"林宪","dynasty":"宋","verses":["孤云不可攀，浩气相与遥。","著亭翠微顶，飞簷侵泬寥。","紫麟迂远驾，黄鹄回扶摇。","云收天籁息，亭影摩重霄。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-60b8e3af-d35e-4f0e-8d1f-ea7c767780b4","tags":[]},{"id":"poem-18af24bba246b40d406f670f","title":"风雨","author":"李商隐","dynasty":"唐","verses":["凄凉宝剑篇，羁泊欲穷年。","黄叶仍风雨，青楼自管弦。","新知遭薄俗，旧好隔良缘。","心断新丰酒，销愁斗几千。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-d32a2610-09d7-49ad-8cdf-dd9c649144c7","tags":["唐诗三百首","风雨","五言律诗","怀才不遇"]},{"id":"poem-18b31a917b84e0170a0f4d01","title":"浣溪沙·钿毂香车过柳堤","author":"张泌","dynasty":"五代","verses":["钿毂香车过柳堤，桦烟分处马频嘶，为他沉醉不成泥。","花满驿亭香露细，杜鹃声断玉蟾低，含情无语倚楼西。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-27","tags":[]},{"id":"poem-18b3e56cdd33c9938cdc61f0","title":"从驾东幸呈诸公","author":"徐铉","dynasty":"宋","verses":["吴公台下旧京城，曾掩衡门过十春。","别后不知新景象，信来空问故交亲。","宦游京口无高兴，习隠钟山限俗尘。","今日喜为华表鹤，况陪鹓鹭免迷津。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-d14b5370-5c90-4958-95fb-d3605413332e","tags":[]},{"id":"poem-18b7d2d773b65a808181a2bb","title":"菩萨蛮·窗前桃蕊娇如倦","author":"纳兰性德","dynasty":"清","verses":["窗前桃蕊娇如倦，东风泪洗胭脂面。","人在小红楼，离情唱《石州》。","夜来双燕宿，灯背屏腰绿。","香尽雨阑珊，薄衾寒不寒。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-178","tags":[]},{"id":"poem-18c06fd9c430bb6e905d529e","title":"西江月·识贯事中枢纽","author":"叶适","dynasty":"宋","verses":["识贯事中枢纽，笔开象外精神。","传观弓力异常钧。","衣我六铢羞问。","周后数茎命粒，鲁儒一点芳心。","啄残栖老付谁论。","谩要睡馀支枕。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-301","tags":[]},{"id":"poem-18c2ac7e6c9b787f6bc4b669","title":"次韵奉酬邓成材判官二首  其二","author":"李纲","dynasty":"宋","verses":["文塲妙誉久推豪，筮仕犹从州县劳。","野鹤未应群鴈鹜，幽兰初不掩蓬蒿。","千寻挺节无霜霰，万里抟风有羽毛。","好去江南吐奇策，从来勋业属吾曹。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-b278963d-9778-4633-b1ec-e69129eba9bc","tags":[]},{"id":"poem-18c3b2a4f88a8cecbeba4116","title":"越中寺居","author":"赵嘏","dynasty":"唐","verses":["迟客疎林下，斜溪小艇通。","野桥连寺月，高竹半楼风。","水静鱼吹浪，枝闲鸟下空。","数峰相向绿，日夕郡城东。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-9ccc71df-4c60-40d5-ae79-ff570ff78bc2","tags":[]},{"id":"poem-18caf51c31880c96b65e6fb5","title":"宿山祠","author":"张籍","dynasty":"唐","verses":["秋草宫人斜里墓，宫人谁送葬来时。","千千万万皆如此，家在边城亦不知。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-ec4bc92d-bd98-4edd-9a32-223db867aebc","tags":[]},{"id":"poem-18cc8cf5ab0eaaa4265c6152","title":"采莲","author":"孙光宪","dynasty":"宋","verses":["菡萏香连十顷陂，小姑贪戏采莲迟。","晚来弄水船头湿，更脱红裙裹鸭儿。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-1b70a53d-87b4-463e-9542-b990b721e07d","tags":["宋词三百首","女子","卷一·唐五代词"]},{"id":"poem-18cddef8e45967f13e9e82ae","title":"送谭浚明归江西","author":"释居简","dynasty":"宋","verses":["恨无玉楮三千幅，尽使春风归约束。","乐饥功谢明月珰，休景息慙芰荷屋。","朋来皎皎歌白驹，不歌长铗弹无鱼。","批风切月瘦弗腴，枕头一束知何书。","欲把列城凭轼下，余子纷纷谩凌跨。","归来袖手如病瘖，舌在何曾问人借。","占灯夜喜傍短檠，剧谭不知山月倾。","元戎后乘沸笳鼓，之子但默黄钟声。","平地邛郲九折坂，十年已恨相逢晚。","四座悲歌漏正迟，一龛风雨花频剪。","镜里功名一横槊，百鸷啾啾空一鹗。","双玉未倾罍未耻，自倒玉山还自起。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-2ee24f3a-a4c4-4a13-ac12-aaab9a18d6bd","tags":[]},{"id":"poem-18cf4477f550e98a132f5331","title":"夜月独坐二绝句  其一","author":"李纲","dynasty":"宋","verses":["冰轮杳杳碾层空，独坐凄然秋色中。","深院无人共清景，静闻金井落梧桐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-25ae1ac6-ad61-4bb2-a5d5-67da1260036d","tags":[]},{"id":"poem-18dd96864c9efdaa3a785376","title":"郊庙歌辞 隐太子庙乐章 迎神","author":"不详","dynasty":"唐","verses":["苍震有位，黄离蔽明。","江充祸结，戾据灾成。","衔冤昔痛，赠典今荣。","享灵有秩，奉乐以迎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-78ae9964-a188-450b-ba7c-7c6386a2a980","tags":[]},{"id":"poem-18de8f74d232aaa3da5412b2","title":"谢程帅袁制使  其三","author":"陈造","dynasty":"宋","verses":["世人事夸毗，失得纷灭起。","回思少年日，失脚几堕此。","尚友千载人，得已吾径已。","高眠北窗风，贤否付一指。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-61d9939b-75ea-40ce-8139-133763f4a354","tags":[]},{"id":"poem-18e45b1e9c45f75912eb77ee","title":"鸨羽","author":"佚名","dynasty":"先秦","verses":["肃肃鸨羽，集于苞栩。王事靡盬，不能蓺稷黍。父母何怙？悠悠苍天，曷其有所？","肃肃鸨翼，集于苞棘。王事靡盬，不能蓺黍稷。父母何食？悠悠苍天，曷其有极？","肃肃鸨行，集于苞桑，王事靡盬，不能蓺稻梁。父母何尝？悠悠苍天，曷其有常？"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-120","tags":[]},{"id":"poem-18ebf4e941db345d23b48239","title":"·空（按《全唐诗》卷五百十及卷五百十一编张祜诗","author":"张祜","dynasty":"唐","verses":["空（按《全唐诗》卷五百十及卷五百十一编张祜诗二卷，又卷八百七十收谐谑诗二首，其中《戏颜郎中骑中骑腊诗》一首已见正卷，盖复出，又卷八百八十三补遗卷有诗五首。","本编所辑四卷，均所未及。","今从北京图书馆藏南宋蜀刻本《张承吉文集》、《永乐大典》、韦庄《又玄集》、《太平广记》引唐康骈《剧谈录》、唐冯翊子《桂苑丛谈》等书录出之。","祜，诸书或有作祐者，误。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-344b4e8a-dcf1-4f1f-b52f-8dd21d9eeee0","tags":[]},{"id":"poem-18ef1dbd8f0d6b5c1545ebe8","title":"题苏仙宅枯松","author":"李涉","dynasty":"唐","verses":["几年苍翠在仙家，一旦枝枯类海槎。","不如酸涩棠梨树，却占高城独放花。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-aff6f954-43c1-41cf-840c-01540f5b4494","tags":[]},{"id":"poem-18ef50985da3d0f758dbbb5c","title":"吊卢殷 八","author":"孟郊","dynasty":"唐","verses":["前贤多哭酒，哭酒免哭心。","后贤试衔之，哀至无不深。","少年哭酒时，白发亦已侵。","老年哭酒时，声韵随生沈。","寄言哭酒宾，勿作登封音。","登封徒放声，天地竟难寻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-2b738b26-0060-4418-8025-38a133c90064","tags":[]},{"id":"poem-18f07859073070bd3463be91","title":"京兆府试目极千里","author":"刘得仁","dynasty":"唐","verses":["献赋多年客，低眉恨不前。","此心常郁矣，纵目忽超然。","送骥登长路，有鸿入远天。","古墟烟幂幂，穷野草绵绵。","树与金城接，山疑桂水连。","何当开霁日，无物翳平川。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-3162fc3c-6966-4a74-a8dc-d7ff9f823bd5","tags":[]},{"id":"poem-18f23e05316ae589d752caf6","title":"赤壁","author":"李商隐","dynasty":"唐","verses":["折戟沈沙铁未销，自将磨洗认前朝。","东风不与周郎便，铜雀春深锁二乔。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-ae660471-84bc-4a58-a438-005b8a99c3c1","tags":["唐诗三百首","隋・唐・五代","战争","八年级下册(课内)","初中古诗","七言绝句","咏史怀古","怀才不遇"]},{"id":"poem-18f604d27d4375e66a719979","title":"雨二首 二","author":"杜甫","dynasty":"唐","verses":["空山中宵阴，微冷先枕席。","回风起清曙，万象萋已碧。","落落出岫云，浑浑倚天石。","日假何道行，雨含长江白。","连樯荆州船，有士荷矛戟。","南防草镇惨，沾湿赴远役。","群盗下辟山，总戎备强敌。","水深云光廓，鸣橹各有适。","渔艇息悠悠，夷歌负樵客。","留滞一老翁，书时记朝夕。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-da0befbd-3655-4d16-8413-0d699c88e75c","tags":["长江"]},{"id":"poem-18ff320f721657968b19ac3b","title":"蒲中道中二首 二","author":"畅当","dynasty":"唐","verses":["古刹栖杮林，绿阴覆苍瓦。","岁晏来品题，拾叶总堪写。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-e7140206-0d47-44c5-a3e2-e325d62c2cc1","tags":[]},{"id":"poem-19088077062694b5fbf44e07","title":"梁源异松图行为台州赵别驾作","author":"林宪","dynasty":"宋","verses":["座中忽觉林樾幽，怪松堕前惊两眸。","孤根蟠错涌鳞鬣，百干奋跃纷戈矛。","千岁之柯海波卷，十亩之阴岚霭浮。","上云变幻舞鸾鹄，下风哮吼搏蛟虬。","影入月窟兔缩距，声撼水府鲸掉头。","初夏花黄醍醐结，四时芽茁绀绿抽。","嘘晴噀雨莽奇怪，摇山荡海寒飕飗。","天开地辟何日种，阴惨阳舒谩神搜。","乡闾讽诵喜辄应，僧伽护爱诃不休。","得非孔明庙前铜柯柏，元气淋漓钟此夫焉廋。","得非道者庵边隔世植万本，伦魁飞来排斡予交樛。","安得此松据此地，轮囷傲蹇无侣俦。","我尝两赋罗汉树，诗人许我不但杨与尤。","一在天台匿峰千岭顶，芘覆方广之寺瀑布流。","一与郡治参云亭对峙，白猿啼蹶忽惊紫凤留。","因知三台气忠厚，何但当代人材优。","至于树木亦豪伟，岁寒动足光林丘。","问诸故老考初始，或云五季方栽培。","黄宋恶迹寺傍庙，野僧无知但包羞。","又云道人梁君隐唐末，建立鼎灶结茅深岩陬。","与二道伴王与白，赤铅紫汞火候卦气周。","千日丹成各升举，舍庵为寺答应求。","后人诞谩附名号，妄踪狂躅何悠悠。","当时丹气蒸山一乡植物茂，丹液入根独此偃盖稠。","势蟠形踞抱龙虎，梢圆叶厚缀球旒。","芘民曾却白额虎，供桃时下青茸猴。","四百余年颇灵异，图经不载记不收。","贤哉赵公眼高远，褒贬万态如春秋。","一见指呼韦偃辈，咄嗟而办造化侔。","竭囊底智老我语，搜搅造化正恐神鬼愁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-b0dfff8d-9ba0-4bc5-b965-decaaead0205","tags":[]},{"id":"poem-19099c1c9d5c5a003343171c","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(小旦)功名事本在天，何必心过虑？且从他得失，任取荣枯。","为人只恐身无艺。","暂时间未从心所欲，金埋土，也须会离土。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2915","tags":[]},{"id":"poem-19109ff298dbc073de739b91","title":"重葺前堂榜曰学易景亮六丈宠惠新诗谨赋二诗上谢  其二","author":"刘跂","dynasty":"宋","verses":["草堂门径迩来通，好事何人肯过雄。","故与图书为伴侣，可无风月到帘栊。","生平适意丝桐内，老去忘怀曲米中。","感激新诗百金重，贫装从此不忧空。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-6f6da4f6-4909-4b3f-991a-9c822851f87c","tags":[]},{"id":"poem-191a0e712c5e799a03442ca3","title":"偈颂七十一首  其一一","author":"释了惠","dynasty":"宋","verses":["天兮高，地兮厚。","月为夜，日为昼。","重阳定是九月九。","渊明采菊向东篱，山僧面南看北斗。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-3ccbbc4c-e528-4ca6-aa9e-4050fba782f6","tags":[]},{"id":"poem-19226a7b04b7ee1ad4e8ab75","title":"东坡谪英州以书语所善衲子曰戒和尚又疏脱矣读之有感","author":"李纲","dynasty":"宋","verses":["东坡夙世乃戒老，次律前身为永师。","一念参差成此错，百忧钟萃使知非。","我生已约渡南海，今日岂知还北归。","从今莫打这鼓笛，必竟是事终由谁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-c38b16f6-e869-44b9-b107-e1bd0da111b3","tags":[]},{"id":"poem-1927b8a8a910b1d6e38d7eb7","title":"赋蕃子牧马","author":"刘言史","dynasty":"唐","verses":["碛净山高见极边，孤烽引上一条烟。","蕃落多晴尘扰扰，天军猎到䴙鹈泉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-75d190fd-838a-4d42-a10b-cb5e0e514fbf","tags":[]},{"id":"poem-19310d455ed012ebc0483316","title":"蝶恋花·红影斑斑吹锦片","author":"毛滂","dynasty":"宋","verses":["红影斑斑吹锦片。","露叶烟梢，寒月娟娟满。","更起绕庭行百遍。","无人祗有栖莺见。","觅个薄情心对换。","愁绪偏长，不信春宵短。","正是碧云音信断。","半衾犹赖香熏暖。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-816","tags":[]},{"id":"poem-1931ec49c3e2c8a9cd959b1f","title":"浣溪沙·旋拂轻容写洛神","author":"纳兰性德","dynasty":"清","verses":["旋拂轻容写洛神，须知浅笑是深颦。","十分天与可怜春。","掩抑薄寒施软障，抱持纤影藉芳茵。","未能无意下香尘。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-59","tags":[]},{"id":"poem-193507c4f4ecb982d2812b80","title":"使青夷军入居庸三首 二","author":"高适","dynasty":"唐","verses":["古镇青山口，寒风落日时。","岩峦鸟不过，冰雪马堪迟。","出塞应无策，还家赖有期。","东山足松桂，归去结茅茨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-80a539fd-75f1-4590-83b2-5c7bf5c0c34c","tags":[]},{"id":"poem-19393f243849c6accc2420e9","title":"鄂渚除夜书怀","author":"来鹄","dynasty":"唐","verses":["鹦鹉洲头夜泊船，此时形影共凄然。","难归故国干戈后，欲告何人雨雪天。","筯拨冷灰书闷字，枕陪寒席带愁眠。","自嗟落魄无成事，明日春风又一年。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-291649a3-b0c3-4d02-b55f-21927738cc04","tags":[]},{"id":"poem-193b0cdff1156479ee589f2a","title":"题竹林寺","author":"朱放","dynasty":"唐","verses":["岁月人间促，烟霞此地多。","殷勤竹林寺，更得几回过？"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-題竹林寺","tags":[]},{"id":"poem-1944a4b6d97da468723305ad","title":"郊庙歌辞 享太庙乐章 凯安四章 三","author":"张说","dynasty":"唐","verses":["总总干戚，填填鼓钟。","奋扬争气，坐作为容。","离若鸷鸟，合如战龙。","万方观德，肃肃雝雝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-fd5cc7ad-fb0e-434e-b731-6967676f7f39","tags":[]},{"id":"poem-194f550d1bd7cd75e5071fc7","title":"宫词","author":"后主衍","dynasty":"唐","verses":["辉辉赫赫浮玉云，宣华池上月华新。","月华如水浸宫殿，有酒不醉真痴人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-ecc1774b-988c-40ea-95f3-312889a6e2a3","tags":[]},{"id":"poem-195257920d4b1ee70ddb0052","title":"绵","author":"佚名","dynasty":"先秦","verses":["绵绵瓜瓞。民之初生，自土沮漆。古公亶父，陶复陶冗，未有家室。","古公亶父，来朝走马。率西水浒，至于岐下。爰及姜女，聿来胥宇。","周原膴膴，堇荼如饴。爰始爰谋，爰契我龟，曰止曰时，筑室于兹。","乃慰乃止，乃左乃右，乃疆乃理，乃宣乃亩。自西徂东，周爰执事。","乃召司空，乃召司徒，俾立室家。其绳则直，缩版以载，作庙翼翼。","捄之陾陾，度之薨薨，筑之登登，削屡冯冯。百堵皆兴，鼛鼓弗胜。","乃立皋门，皋门有伉。乃立应门，应门将将。乃立冢土，戎丑攸行。","四不殄厥愠，亦不陨厥问。柞棫拔矣，行道兑矣。混夷駾矣，维其喙矣！","虞芮质厥成，文王蹶厥生。予曰有疏附，予曰有先后。予曰有奔奏，予曰有御侮！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-236","tags":[]},{"id":"poem-195d0673d6d72c429794c956","title":"宿云门寺阁","author":"孙逖","dynasty":"唐","verses":["香阁东山下，烟花象外幽。","悬灯千嶂夕，卷幔五湖秋。","画壁余鸿雁，纱窗宿斗牛。","更疑天路近，梦与白云游。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-宿雲門寺閣","tags":[]},{"id":"poem-195e13a1dfed27d5598eeb66","title":"贫女","author":"秦韬玉","dynasty":"唐","verses":["蓬门未识绮罗香，拟托良媒益自伤。","谁爱风流高格调，共怜时世俭梳妆。","敢将十指夸偏巧，不把双眉鬬画长。","苦恨年年压金线，为他人作嫁衣裳。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-16ddf43c-ac3a-47bc-95a5-36a49bceb30b","tags":["唐诗三百首","哲理","七言律诗","生活","女子","怀才不遇"]},{"id":"poem-195fa4a9352d4dddc0f049fb","title":"鸤鸠","author":"佚名","dynasty":"先秦","verses":["鸤鸠在桑，其子七兮。淑人君子，其仪一兮。其仪一兮，心如结兮。","鸤鸠在桑，其子在梅。淑人君子，其带伊丝。其带伊丝，其弁伊骐。","鸤鸠在桑，其子在棘。淑人君子，其仪不忒。其仪不忒，正是四国。","鸤鸠在桑，其子在榛。淑人君子，正是国人，正是国人。胡不万年？"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-151","tags":[]},{"id":"poem-1963b36033457e491f7624a1","title":"木兰花・玉楼春·秋千院落重帘暮","author":"晏几道","dynasty":"宋","verses":["秋千院落重帘暮。","彩笔闲来题绣户。","墙头丹杏雨馀花，门外绿杨风后絮。","朝云信断知何处。","应作襄王春梦去。","紫骝认得旧游踪，嘶过画桥东畔路。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-26","tags":["宋词三百首"]},{"id":"poem-1965b9a06a6f6132280aa2c7","title":"题不欺室张魏公为王龟龄书也何子应赋诗","author":"王秬","dynasty":"宋","verses":["君不见开元名相张九龄，岁寒松柏森苍鳞。","胡尘澒洞言始验，世间回首思忠臣。","堂堂魏公忠贯日，志欲平戎奖王室。","归来无地展经纶，余事文章挥健笔。","玉节朱轓两君子，不以交情变生死。","共将新句纪遗编，留与山林续诗史。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-0f36b0c7-7c58-4560-b805-fee122d6415a","tags":[]},{"id":"poem-1967183b7b01a1d40b827ceb","title":"过津口","author":"杜甫","dynasty":"唐","verses":["南岳自兹近，湘流东逝深。","和风引桂楫，春日涨云岑。","回首过津口，而多枫树林。","白鱼困密网，黄鸟喧嘉音。","物微限通塞，恻隐仁者心。","瓮余不尽酒，膝有无声琴。","圣贤两寂寞，眇眇独开襟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-c64edbb6-04bf-4e6d-bc04-8cd4f0e0df72","tags":[]},{"id":"poem-196c6da4a58157d9c8aeee89","title":"定西番·海燕欲飞调羽","author":"温庭筠","dynasty":"唐","verses":["海燕欲飞调羽。萱草绿，杏花红，隔帘栊。","双鬓翠霞金缕，一枝春艳浓。","楼上月明三五，琐窗中。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-27","tags":[]},{"id":"poem-196e62b90bb477aef5446cfd","title":"题时遁泽画卷十首  其一","author":"王柏","dynasty":"宋","verses":["断岸临江渚，风声瑟瑟寒。","苍髯五君子，莫作大夫看。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-156b7c26-c3a9-417f-aec1-9187a273cd45","tags":[]},{"id":"poem-196f10ecdca3dee72c26b7b3","title":"游贾氏南园","author":"韩缜","dynasty":"宋","verses":["江堤杨柳碧毵毵，闲访名园郡郭南。","垅麦生齐知雨足，海棠开遍觉春酣。","门前幽径通芳蕙，竹里虚亭对远岚。","风物有情应笑我，不携歌酒只清谈。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-a990d84f-f01a-4353-9e54-fe03c6db1101","tags":[]},{"id":"poem-1970419ea91b629ec94c54c6","title":"客有出示御制登中和堂诗小臣斐然仰次宸韵二首  其二","author":"李纲","dynasty":"宋","verses":["贱子志丘壑，敢怀要路津。","偶乘风云会，冀拯凋瘵民。","误被圣主知，坐期功业新。","飘零继三黜，奔走亦已勤。","生还鲸海中，仰荷皇天仁。","不然铄金口，何有鸿毛身。","当从玄豹隐，无复尺蠖伸。","感叹魏公言，愿使为良臣。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-52644717-47bc-445f-b17d-411b19b39037","tags":[]},{"id":"poem-1972f3a1b1e48c79e685eadc","title":"新安故关","author":"孟迟","dynasty":"唐","verses":["汉帝英雄重武材，崇山险处凿门开。","如今更有将军否，移取潼关向北来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-5580c982-d27d-40fb-9cee-c20e2bdda267","tags":[]},{"id":"poem-197361d39df4918b12848de7","title":"扈驾西山","author":"纳兰性德","dynasty":"清","verses":["凤翥龙蟠势作环，浮青不断太行山。","九重殿阁葱茏里，一气风云吐纳间。","熊虎自当驰道伏，蛟螭长棒御书闲。","黄图此日论形胜，惭愧频叨侍从班。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-242","tags":[]},{"id":"poem-1978360758bb7fefcee1c563","title":"浪淘沙·帘外微风","author":"杜安世","dynasty":"宋","verses":["帘外微风。","云雨回踪。","银釭烬冷锦帏中。","枕上深盟，年少心事，陡顿成空。","岭外白头翁。","到没由逢。","一床鸳被叠香红。","明月满庭花似绣，闷不见虫虫。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-913","tags":[]},{"id":"poem-1982029392688828effbae32","title":"兵要望江南 占六壬第二十八（京本列第十七○四十五首） 二十四","author":"易静","dynasty":"唐","verses":["三传将，遥日（辛本、川本、京本作「见」）觅支干。","将见支干休进战，三神被克我军（京本作「神」）安，必获彼旗旛。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-3263917a-5d1c-4a26-832a-51e6c141a37f","tags":[]},{"id":"poem-198804bd12357e588d6b7d9d","title":"早春送颜主簿游越东兼谒元中丞","author":"皎然","dynasty":"唐","verses":["轻舸趣不已，东风吹绿苹。","欲看梅市雪，知赏柳家春。","别意倾吴醑，芳声动越人。","山阴三月会，内史得嘉宾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-a7c5039b-ea20-46df-ae06-1e116034b1d3","tags":[]},{"id":"poem-198b9018e0f02e86caa9c94a","title":"昭君怨三首 一","author":"东方虬","dynasty":"唐","verses":["汉道方全盛，朝廷足武臣。","何须薄命妾，辛苦事和亲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-aa7be51f-e588-45a0-87db-e727a54b9d88","tags":[]},{"id":"poem-198d0017dd43dc9027e24c7f","title":"减字木兰花·从教铁石","author":"纳兰性德","dynasty":"清","verses":["从教铁石，每见花开成惜惜。","泪点难消，滴损苍烟玉一条。","怜伊大冷，添个纸窗疏竹影。","记取相思，环佩归来月上时。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-209","tags":[]},{"id":"poem-19a00c8ad77d6971b7a69578","title":"积翠峰","author":"延寿","dynasty":"唐","verses":["翠压群峰地形直，落日猿声在空碧。","天风吹散断崖云，古松长露三秋色。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-58fad443-2c81-439e-8831-9a1284a289ed","tags":[]},{"id":"poem-19a256a692e50193620a19f6","title":"碧玉泉","author":"陈岩","dynasty":"宋","verses":["蕴玉含晖一水间，碧光炯炯照人寒。","却疑洗出荆山璞，若有瑕疵试指看。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-b5517cdf-6c52-4bf8-89ed-8029de5a089e","tags":[]},{"id":"poem-19b07798e367222fff1e7d4b","title":"玉联环・解连环·都人未逐风云散","author":"张先","dynasty":"宋","verses":["都人未逐风云散。","愿留离宴。","不须都爱洛城春，黄花讶、归来晚。","叶落灞陵如翦。","泪沾歌扇。","无由重肯日边来，上马便、长安远。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-298","tags":[]},{"id":"poem-19b2eadab7b45fbd4b094c5f","title":"菩萨蛮 其一","author":"温庭筠","dynasty":"唐","verses":["小山重叠金明灭，鬓云欲度香腮雪。","懒起画蛾眉，弄妆梳洗迟。","照花前后镜，花面交相映。","新帖绣罗襦，双双金鹧鸪。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-0","tags":[]},{"id":"poem-19b5998e002407070034a152","title":"偶题二首 一","author":"徐夤","dynasty":"唐","verses":["买骨须求骐骥骨，爱毛宜采凤皇毛。","驽骀燕雀堪何用，仍向人前价例高。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-409ac501-f726-41d2-b592-d21557e75699","tags":[]},{"id":"poem-19bac83dad62c38dabd6d7e9","title":"南游有怀","author":"龚霖","dynasty":"唐","verses":["怀才非独步，驱马出荆州。","亲老未归去，路长何处游？","鸟啼云梦晓，叶落洞庭秋。","襟抱谁相问？西风吹客愁。","（同前书第二六九页。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-c2b9d035-3faf-422d-9b74-7341002eae5f","tags":["洞庭湖"]},{"id":"poem-19bb60d70cfa70590734736c","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["不须多忧，送婆婆是我身下有。","你但小心承直公公，莫教又成不救。","(合前)(旦白)如此，谢得公公！只为无钱送老娘。","(末白)娘子放心，须知此事有商量。","(合)正是：归家不敢高声哭，只恐人闻也断肠。","(并下)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5082","tags":[]},{"id":"poem-19bf0886dcd29f28570deb4c","title":"后苦寒行二首 一","author":"杜甫","dynasty":"唐","verses":["南纪巫庐瘴不绝，太古以来无尺雪。","蛮夷长老怨苦寒，昆仑天关冻应折。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-edfab8d8-0b21-4198-b103-275f0433a339","tags":[]},{"id":"poem-19c1f0ea734ab5ae56036092","title":"溱洧","author":"佚名","dynasty":"先秦","verses":["溱与洧，方涣涣兮。士与女，方秉𫈉兮。女曰观乎？士曰既且。且往观乎？","洧之外，洵𬣙且乐。维士与女，伊其相谑，赠之以勺药。","溱与洧，浏其清矣。士与女，殷其盈矣。女曰观乎？士曰既且。且往观乎？","洧之外，洵𬣙且乐。维士与女，伊其将谑，赠之以勺药。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-94","tags":[]},{"id":"poem-19c2c2823df5c4434f594afa","title":"始为奉礼忆昌谷山居","author":"李贺","dynasty":"唐","verses":["扫断马蹄痕，衙回自闭门。","长鎗江米熟，小树枣花春。","向壁悬如意，当帘阅角巾。","犬书曾去洛，鹤病悔游秦。","土甑封茶叶，山杯锁竹根。","不知船上月，谁櫂满溪云。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-1bec046f-3d2a-4202-8402-29a7f60269ee","tags":[]},{"id":"poem-19ce1af15c56db9e0f32fb70","title":"赋东城梅花示哲上人","author":"綦崇礼","dynasty":"宋","verses":["一枝冷落为谁开，欲遣寒香入酒杯。","铁石心肠犹解赋，芝兰风味合相陪。","腊前颇讶疏疏见，春尽何妨得得来。","十里东城不嫌远，待看山月照徘徊。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-2d1d41e3-cb42-45dc-be92-0b8717de4cf7","tags":[]},{"id":"poem-19d4896575aaab4c7cd488dc","title":"神功盛德诗  其二五","author":"华镇","dynasty":"宋","verses":["绵绵句丽，莽莽河湟。","绝彼东海，逸于西疆。","或翦或怀，德威孔扬。","列我郡县，袭我衣裳，于前人有光。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-f585df62-d5d2-4225-a170-47e029f70dfd","tags":[]},{"id":"poem-19d91d4bbcf9fb89fe307f46","title":"东门之𫮃","author":"佚名","dynasty":"先秦","verses":["东门之𫮃，茹藘在阪。其室则迩，其人甚远。","东门之栗，有践家室。岂不尔思？子不我即！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-88","tags":[]},{"id":"poem-19de77e7e2018bb58a45ab99","title":"柳枝·软碧瑶烟似送人","author":"和凝","dynasty":"五代","verses":["软碧瑶烟似送人，映花时把翠蛾颦。","青青自是风流主，慢飐金丝待洛神。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-29","tags":[]},{"id":"poem-19e0de17e100d089cc9b2a2c","title":"游终南山因寄苏奉礼士尊师苗员外","author":"李端","dynasty":"唐","verses":["半岭逢仙驾，清晨独采芝。","壶中开白日，雾里卷朱旗。","猨鸟知归路，松萝见会时。","鸡声传洞远，鹤语报家迟。","童子闲驱石，樵夫乐看棋。","依稀醉后拜，恍惚梦中辞。","海上终难接，人间益自疑。","风尘甘独老，山水但相思。","愿得烧丹诀，流沙永待师。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-a13d5995-b530-465b-84bc-b3c847dd1c44","tags":["终南山"]},{"id":"poem-19e384fdeb6ba4cb68b28b5e","title":"梅花引","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["伤心满目故人疏，看郊墟尽荒芜。","(旦贴上唱)惟有青山，添得个坟墓。","(合)恸哭无由长夜晓，问泉下有人还听得无？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5260","tags":[]},{"id":"poem-19eab1d465121c7ad9681d65","title":"硕鼠","author":"佚名","dynasty":"先秦","verses":["硕鼠硕鼠，无食我黍！三岁贯女，莫我肯顾。逝将去女，适彼乐土。乐土乐土，爰得我所。","硕鼠硕鼠，无食我麦！三岁贯女，莫我肯德。逝将去女，适彼乐国。乐国乐国，爰得我直。","硕鼠硕鼠，无食我苗！三岁贯女，莫我肯劳。逝将去女，适彼乐郊。乐郊乐郊，谁之永号？"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-112","tags":[]},{"id":"poem-19fdda1a561bfdadf2e04c95","title":"调笑・调笑令·芳草","author":"毛滂","dynasty":"宋","verses":["芳草。","恨春老。","自是寻春来不早。","落花风起红多少。","记得一枝春小。","绿阴青子空相恼。","此恨平生怀抱。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-895","tags":[]},{"id":"poem-1a091278402080cf3f1816e6","title":"洋州三十景 书轩","author":"鲜于侁","dynasty":"宋","verses":["朱门谢俗客，幽斋叙友人。","澄澜鉴止水，高节看丛筠。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-f7ad18db-7ddc-45f8-baba-5e4292b39332","tags":[]},{"id":"poem-1a15ab132842d48ab98dc6eb","title":"吊建州李员外","author":"张乔","dynasty":"唐","verses":["铭旌归故里，猿鸟亦凄然。","已葬桐江月，空回建水船。","客传为郡日，僧说读书年。","恐有吟魂在，深山古木边。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-d8ed88d6-e73a-42e1-bc4b-f0c36870e5e7","tags":[]},{"id":"poem-1a16f6b540b10c91e60aeeff","title":"宫中题","author":"李昂","dynasty":"唐","verses":["辇路生秋草，上林花满枝。","凭高何限意，无复侍臣知。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-宮中題","tags":[]},{"id":"poem-1a1a756ea6a4f01e34c4695a","title":"句","author":"徐常","dynasty":"宋","verses":["词赋切宜师二宋，文章须是学三苏。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-d63bd132-811b-4f02-9a59-11c5e55a0ee7","tags":[]},{"id":"poem-1a1dee483b705a21ee4a7481","title":"红绣鞋","author":"徐田臣《杀狗记》","dynasty":"元","verses":["明日办个筵席，筵席，把家私付与兄弟，兄弟。","(小生)谢哥哥转心意，结义的再休题。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1931","tags":[]}];
